(window.MATRIX_DATA_PARTS ||= Object.create(null))["data/poems-0011.js"] = [{"id":"poem-49b1d0b109ab068555b9766b","title":"题马远作四皓弈棋图横卷","author":"米芾","dynasty":"宋","verses":["落落四皓翁，山林养其静。","羞为汉家臣，若辟秦苛政。","商颜高峨峨，坐待天下定。","欻起佐储皇，上前启名姓。","堪怜羽翼成，难将口舌争。","无语及扶苏，空歌紫芝咏。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.60000.json#record-7649c70d-88a1-4a3c-8c80-0d24cda7bec3","tags":[]},{"id":"poem-49c67b15a51cd05918395986","title":"祀雨师乐章 亚献终献","author":"包佶","dynasty":"唐","verses":["奠既备，献将终。","神行令，瑞飞空。","迎干德，祈岁功。","乘烟燎，俨从风。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-d09d1609-8bf2-4982-82e3-83cce2ef2a91","tags":[]},{"id":"poem-49c7ea3b366c3ab82b0bc198","title":"谢赐珍珠","author":"江妃","dynasty":"唐","verses":["桂叶双眉久不描，残妆和泪汚红绡。","长门尽日无梳洗，何必珍珠慰寂寥。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-06c84041-b4d9-4317-8d51-863fe37b087b","tags":["思念","女子","宫怨"]},{"id":"poem-49ccada9fd6c7f7358c11b76","title":"送王尊师归湖州","author":"司空曙","dynasty":"唐","verses":["烟芜满洞青山遶，幢节飘空紫凤飞。","金阙乍看迎日丽，玉箫遥听隔花微。","多开石髓供调膳，时御霓裳奉易衣。","莫学辽东华表上，千年始欲一回归。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-a9a12ca0-3896-4787-a112-d9cbc41bac60","tags":[]},{"id":"poem-49da98a7412846010b3e3eb1","title":"渔歌子·泛流萤","author":"孙光宪","dynasty":"五代","verses":["泛流萤，明又灭，夜凉水冷东湾阔。","风浩浩，笛寥寥，万顷金波澄澈。","杜若洲，香郁烈，一声宿雁霜时节。","经霅水，过松江，尽属侬家日月。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-8-juan.json#record-47","tags":[]},{"id":"poem-49dd5d477a8f0b68dd3eb153","title":"秋霁·木落山明","author":"曾纡","dynasty":"宋","verses":["木落山明，暮江碧，楼倚太虚寥廓。","素手飞觞，钗头笑取，金英满浮桑落。","鬓云慢约。","酒红拂破香腮薄。","细细酌。","帘外任教、月转画阑角。","当年快意登临，异乡节物，难禁离索。","故人远、凌波何在，惟有残英共寂寞。","愁到断肠无处著。","寄寒香与，凭渠问讯佳时，弄粉吹花，为谁梳掠。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.2000.json#record-68","tags":[]},{"id":"poem-4a081b3d2d313830e8d61d5e","title":"题水月台","author":"李涉","dynasty":"唐","verses":["平流白日无人爱，桥上闲行若个知。","水似晴天天似水，两重星点碧琉璃。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-80e98e34-908e-4480-9240-b0a874b552e0","tags":[]},{"id":"poem-4a0aed449483401c5322a490","title":"从军行","author":"崔国辅","dynasty":"唐","verses":["塞北胡霜下，营州索兵救。","夜里偷道行，将军马亦瘦。","刀光照塞月，阵色明如昼。","传闻贼满山，已共前锋鬬。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-7dc010f6-30c6-4041-a0f5-3b8f33c6e46e","tags":[]},{"id":"poem-4a1791e1b56d3985abf5918e","title":"小游仙诗九十八首 四十一","author":"曹唐","dynasty":"唐","verses":["酒尽香残夜欲分，青童拜问紫阳君。","月光悄悄笙歌远，马影龙声归五云。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-3d9aaf41-bddd-4040-907b-73b56b50c5c5","tags":[]},{"id":"poem-4a22ad47c62c8ee24818f988","title":"鹦鹉","author":"来鹄","dynasty":"唐","verses":["色白还应及雪衣，觜红毛绿语仍奇。","年年锁在金笼里，何似陇山闲处飞。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-a49e6c91-9d64-47a5-8cab-3060d1b3ed94","tags":[]},{"id":"poem-4a22e7f4905cd2ca5fcc4464","title":"台城","author":"韦庄","dynasty":"唐","verses":["江雨霏霏江草齐，六朝如梦鸟空啼。","无情最是台城柳，依旧烟笼十里堤。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-9154fc22-5e19-45b7-a506-435298bb26fc","tags":["唐诗三百首","隋・唐・五代","写景","抒情","咏史怀古"]},{"id":"poem-4a2378bede1e9aa8ac67f769","title":"诗品二十四则 超诣","author":"司空图","dynasty":"唐","verses":["匪神之灵，匪机之微。","如将白云，清风与归。","远引若至，临之已非。","少有道契，终与俗违。","乱山高木，碧苔芳晖。","诵之思之，其声愈稀。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-f4442282-304d-4418-a7b2-683aa859e9e2","tags":[]},{"id":"poem-4a2b2b3c16458b6fdec7310f","title":"雨后复旱呼海嵎山龙浃旬复大霔  其二","author":"释居简","dynasty":"宋","verses":["久矣惟心祷，呼龙徇物情。","均沾四郊足，不负九推耕。","蚌活沙头脯，鶑新雨后声。","娄丰斯在望，老瓦醉秋成。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.180000.json#record-782fd17f-6b48-48d4-a811-d7ddc2c630f7","tags":[]},{"id":"poem-4a3705e45c9ab2aa8f112b22","title":"移居静安坊答元八郎中","author":"张籍","dynasty":"唐","verses":["长安寺里多时住，虽守卑官不苦贫。","作活每常嫌费力，移居祗是贵容身。","初开井浅偏宜树，渐觉街闲省踏尘。","更喜往还相去近，门前减却送书人。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-5ee04935-b05b-427d-be12-d1015dfabff7","tags":[]},{"id":"poem-4a397f7914b3f614156c3e8c","title":"题广爱寺楞伽山","author":"李琪","dynasty":"唐","verses":["善高天外远，方丈海中遥。","自有山神护，应无劫火烧。","坏文侵古壁，飞剑出寒霄。","何似苍苍色，严妆十七朝。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-ea069414-3057-4b62-ace3-b1258ed5c167","tags":[]},{"id":"poem-4a48b9b7d8d305da16f12035","title":"汪廷俊见示喜雨和篇次韵答之二首  其二","author":"李纲","dynasty":"宋","verses":["悯旱遥将精意通，秋霖霶霈仰旻穹。","山川增焕家家好，黍稷方华物物丰。","得句自应髭变白，举觞何惜颊潮红。","他时倘会风云便，肯倒长瓢学卫公。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.90000.json#record-6827b88a-ade6-4021-aabc-1cb8044be5c5","tags":[]},{"id":"poem-4a4aa04eb5cc1bc1b5918b19","title":"水底鱼","author":"施惠《幽闺记》","dynasty":"元","verses":["(净上)三世行医，四方人尽知。","不论贵贱。","请着的即便医。","卢医扁鹊，料他直甚的？人人道我，道我是个催命鬼。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-2997","tags":[]},{"id":"poem-4a4dd9aca31c899386eac7a5","title":"水底鱼","author":"柯丹邱《荆钗记》","dynasty":"元","verses":["［生上］仰之弥高，钻之弥坚，忽焉在后，赡之忽在前。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-8041","tags":[]},{"id":"poem-4a50a96da5f6470527925a87","title":"次韵李粹伯登镇江倅厅富览亭","author":"曾协","dynasty":"宋","verses":["酒余共逍遥，散步升高冈。","万物困霜雪，岁晏俱老苍。","江山一临眺，志欲凌八荒。","青霞傥见分，谁能束冠裳。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.120000.json#record-88e21c0f-7d2a-4655-a049-04ed53aeba43","tags":[]},{"id":"poem-4a52e746b47fad776279b63a","title":"前腔","author":"刘唐卿《白兔记》","dynasty":"元","verses":["严冬天气，彤云布密，满空飞。","只见上下同一色。","于山失翠微。","画阁红炉深处，画阁红炉深处，欢宴饮琼卮。","相公，我和你满拚沉醉，共乐共乐销金帐取。","(合前。","小生扮咬脐上)。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-8971","tags":[]},{"id":"poem-4a55270fec9884dc31a33019","title":"赋得早雁出云鸣","author":"太宗皇帝","dynasty":"唐","verses":["初秋玉露清，早雁出空鸣。","隔云时乱影，因风乍含声。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-c353940d-4bbc-4420-83bf-07cb4606d35f","tags":[]},{"id":"poem-4a58d0ebab0767ea520f7c0a","title":"木兰花・玉楼春·江云叠叠遮鸳浦","author":"苏庠","dynasty":"宋","verses":["江云叠叠遮鸳浦。","江水无情留薄暮。","归帆初张苇边风，客梦不禁篷背雨。","渚花不解留人住。","只作深愁无尽处。","白沙烟树有无中，雁落沧洲何处所。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.4000.json#record-695","tags":[]},{"id":"poem-4a5b9cceae9f1097c2fd9958","title":"莺梭","author":"刘克庄","dynasty":"宋","verses":["掷柳迁乔太有情，交交时作弄机声。","洛阳三月花如锦，多少工夫织得成。"],"enabled":true,"collection":"千家诗","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/蒙学/qianjiashi.json#record-鶯梭","tags":[]},{"id":"poem-4a61addde2f589f41ae69a12","title":"元日","author":"王安石","dynasty":"宋","verses":["爆竹声中一岁除，春风送暖入屠苏。","千门万户曈曈日，总把新桃换旧符。"],"enabled":true,"collection":"千家诗","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/蒙学/qianjiashi.json#record-元日","tags":[]},{"id":"poem-4a6b655c6071c798c01dd50b","title":"献蔡京","author":"张顶","dynasty":"唐","verses":["抛却长竿卷却丝，手持蓑笠献新诗。","临川太守清如镜，不是渔人下钓时。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-e3bb0eb8-5bf2-4489-9edf-1ff56178c787","tags":[]},{"id":"poem-4a780040423528be1a482331","title":"缺题 一","author":"王操","dynasty":"唐","verses":["分飞南渡春风晚，却返家林旧业空。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-97b1822c-0b69-4c3a-b083-87e70cd13d19","tags":[]},{"id":"poem-4a7c8c03840f933194e3130c","title":"程帅和陶二诗见忆次韵","author":"陈造","dynasty":"宋","verses":["我瞻西郊，云停不雨。","鸡栖乱山，十舍千阻。","一书缄春，慰厉存抚。","望之或违，搔首企伫。","停云酾之，蜚雨蒙蒙。","启筒有获，如渴吸江。","孤月河汉，轻飔牖窗。","忆侍诲色，杖屦后从。","盱衡推予，褒衮俪荣。","靡怀不倾，靡言不情。","会晤良难，欻然西征。","孰谓愁斛，无自而生。","竹萌触雪，粟花缀柯。","风日山城，未春已和。","命驾取涂，计日不多。","官曹简书，公其谓何。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.150000.json#record-97e56361-a8eb-4fe3-8966-4ca45d8c2dbd","tags":[]},{"id":"poem-4a88c206fb2f87a534abf941","title":"和光道元日书事二首  其二","author":"华镇","dynasty":"宋","verses":["急管妖弦朝暮闻，翠帘下应当垆君。","叫呼枭卢一百万，砍削兕脯三千斤。","孔座嘉客每日满，杨园细草何须耘。","夜长秉烛可为乐，春色三分未一分。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.60000.json#record-9869145f-076e-47ce-b7fd-5b537f7234d1","tags":[]},{"id":"poem-4a8fc145ebaad7f01bc89183","title":"香罗带","author":"刘唐卿《白兔记》","dynasty":"元","verses":["(旦)衙内听拜禀，(拜介。","小生作倒介)不要拜了。","(旦)容奴说事因。","一从间别鸾凤两处分，被哥哥嫂嫂苦逼分离也。","朝朝挑水，夜夜辛勤。","日日泪珠暗零。","(合)异日说冤，恨取薄幸人，苦也天天，甚日得母子团圆说事因？。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-8976","tags":[]},{"id":"poem-4a90a250155b650ad1ecccac","title":"悼汪舍人养源","author":"王十朋","dynasty":"宋","verses":["襆被周庐日，寅缘识伟人。","节因辞辟著，志向得言伸。","伯仲同持橐，声名压缙绅。","人亡邦国瘁，可赎百其身。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.120000.json#record-33b1c241-2240-4724-b0c1-51350c8eaa94","tags":[]},{"id":"poem-4aa20e9f6f6872bc39972083","title":"述怀  其一","author":"王镃","dynasty":"宋","verses":["平生自笑拙经营，薄有泉田税犊耕。","实地立身终是稳，权门炙手不为荣。","孤山名以吟梅重，彭泽官因爱菊轻。","尘世几人贪富贵，可怜头白竟无成。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.240000.json#record-b96b8fc7-06a8-4f92-a677-44ed1e806a80","tags":[]},{"id":"poem-4aaa716e6cf870f86bc4c268","title":"瀑布","author":"江为","dynasty":"唐","verses":["庐山正南面，瀑布古来闻。","万里朝沧海，千寻出白云。","寒声终自远，灵派孰为分。","除却天台后，平流莫可群。","（录自《吉石盦丛书》本宋陈舜俞《庐山记》卷四。","）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-07298ab8-838f-4494-b77a-5d448bf01804","tags":["庐山"]},{"id":"poem-4aaa8a9f08cee742cdc4d8d7","title":"臯桥","author":"李绅","dynasty":"唐","verses":["伯鸾憔悴甘飘寓，非向嚣尘隐姓名。","鸿鹄羽毛终有志，素丝琴瑟自谐声。","故桥秋月无家照，古井寒泉见底清。","犹有余风未磨灭，至今乡里重和鸣。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-78e1c384-29e2-46e9-aff3-0d400ba702b8","tags":[]},{"id":"poem-4abd166a4db231a8f1c33cf8","title":"送边上从事","author":"周繇","dynasty":"唐","verses":["戎装佩镆鎁，走马逐轻车。","衰草城边路，残阳垄上笳。","黄河穿汉界，青冢出胡沙。","提笔男儿事，功名立可夸。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-6b74a409-0c54-4a99-a245-972e4189538a","tags":["黄河"]},{"id":"poem-4abdbd47ad96737eb22b755e","title":"河传·春晚","author":"韦庄","dynasty":"五代","verses":["春晚，风暖，锦城花满。","狂杀游人，玉鞭金勒，寻胜驰骤轻尘，惜良晨。","翠娥争劝临邛酒，纤纤手，拂面垂丝柳。","归时烟里，钟鼓正是黄昏，暗销魂。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-3-juan.json#record-5","tags":[]},{"id":"poem-4ac7f00a92a608dba9d2fe7b","title":"慈恩寺东楼","author":"曹松","dynasty":"唐","verses":["寺楼凉出竹，非与曲江赊。","野火流穿苑，秦山叠入巴。","风梢离众叶，岸角积虚沙。","此地钟声近，令人思未涯。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-97569e1c-7bac-4799-a644-b84a7662e152","tags":[]},{"id":"poem-4acaa5b53dd5873aef1ba308","title":"题平远轩呈竹溪玉堂","author":"刘翼","dynasty":"宋","verses":["溪堂辟小轩，此景绝可爱。","蔡松道东边，千载典刑在。","高低万顷田，面势溪向背。","生绡一幅宽，晴雨不尽态。","中有谪仙人，来寻莘野耒。","畎亩虽不忘，知进不如退。","乾坤入醉眼，风月出吟喙。","我非人境游，亭在人境内。","心平水不波，见远山无碍。","时携琰石游，间以刘白辈。","仆忝老诸生，来扣佛三昧。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.210000.json#record-036bb7c5-8c03-40db-a1d8-681c81620bd4","tags":[]},{"id":"poem-4acc6627f67a7a90b4aabc6a","title":"奉和武功学士舍人纪赠文懿大师浄公  其九","author":"徐铉","dynasty":"宋","verses":["霜髯病叟掩闲扃，禅客相寻有故情。","每忆江南初识面，至今犹得爱才名。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.0.json#record-d301ad2b-1a82-4152-8a24-7e099596f686","tags":[]},{"id":"poem-4ad6183b015dad5663f173bf","title":"秋日湖上","author":"薛莹","dynasty":"唐","verses":["落日五湖游，烟波处处愁。","浮沉千古事，谁与问东流。"],"enabled":true,"collection":"千家诗","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/蒙学/qianjiashi.json#record-秋日湖上","tags":[]},{"id":"poem-4ae2257139cb0731dfd74a56","title":"和三乡诗","author":"李昌邺","dynasty":"唐","verses":["红粉萧娘手自题，分明幽怨发云闺。","不应更学文君去，泣向残花归剡溪。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-69cd0bcd-9e58-4660-a48e-e5ee47e62232","tags":[]},{"id":"poem-4ae796046da32ab9d6d554f8","title":"无题（伯三一九七）","author":"卢茂钦","dynasty":"唐","verses":["躺游仙院覩灵台，罗绮分明塑匠裁。","高绾绿鬟{髟/云}（云）髻重，手垂罗袖牡丹开。","（「手垂」，项目疑当作「平垂」，与「高绾」为对。","）容仪一见情难舍，玉貌重看意嬾回。","若表恳成（诚）心所志，愿将恣貌梦中来。","（「恣」，蒋、项皆云当作「姿」。","）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-e7e4d2f0-31ec-4781-8a6c-1708f7fe618a","tags":[]},{"id":"poem-4ae9ad189be54f82647e7d75","title":"凤凰台上忆吹箫·才短宫慵","author":"晁补之","dynasty":"宋","verses":["才短宫慵，命奇人弃，年年故里来远。","记往岁、莲塘送我，远赴荆蛮。","莫道风情似旧，青镜里、绿鬓新斑。","佳人怪，把盏为我，微敛眉山。","从来嗣宗高韵，独见赏，青云忧绝尘间。","谩回首、平生醉语，一梦惊残。","莫笑移花种柳，应备办、投老同闲。","纵枯槁，松桧奈得霜寒。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.4000.json#record-129","tags":[]},{"id":"poem-4aeb117c0b774c6daff10093","title":"河传·湖上","author":"温庭筠","dynasty":"唐","verses":["湖上，闲望。","雨萧萧，烟浦花桥路遥。","谢娘翠蛾愁不消，终朝，梦魂迷晚潮。","荡子天涯归棹远，春已晚，莺语空肠断。","若耶溪，溪水西，柳堤，不闻郎马嘶。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-2-juan.json#record-9","tags":[]},{"id":"poem-4af03c5df1b1e85c9b517611","title":"华阴道中逢月出","author":"赵匡胤","dynasty":"唐","verses":["未离海底（《藏一话腴》作「峤」）千山黑（《扪虱新话》作「暗」），才到天中（《扪虱新话》作「中天」、《藏一话腴》作「天心」）万国明。","（见《后山诗话》，校以《说郛》本《藏一话腴》、陈善《扪虱新话》卷二。","题从《扪虱新话》。","《藏一话腴》谓此二句系国史据《日诗》）润色之。","（按：宋人均记载匡胤二诗为其微时作。","若可信，当作于晋汉之际。","）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-fe288826-38b3-4e3c-b350-e7b87aa610c6","tags":[]},{"id":"poem-4af45a233e3b81d8cb975da9","title":"谒云蓝山先越公墓","author":"汪宗臣","dynasty":"宋","verses":["此生未展云蓝墓，鬰鬰甘棠孙子情。","今度忽为寒食客，欣欣乔木岁时荣。","尧天日月重光显，越国江山几变更。","回首千年有归鹤，练溪新涨匝春城。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.240000.json#record-7036a3a0-133f-4292-aa80-842d89f44b5d","tags":[]},{"id":"poem-4aff278ca53d676163f8c7f9","title":"咏史诗 易水","author":"胡曾","dynasty":"唐","verses":["一旦秦皇马角生，燕丹归北送荆卿。","行人欲识无穷恨，听取东流易水声。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-11c5e9ca-8713-46c7-9ed8-98371093cfee","tags":[]},{"id":"poem-4b02c5c3e3f90752a64c9ed8","title":"一丛花·碧山无意解银鱼","author":"晁补之","dynasty":"宋","verses":["碧山无意解银鱼。","花底且携壶。","华颠又喜熊罴且，笑骐骥，老反为驹。","文史渐抛，功名更懒，随处见真如。","高情敢并汉庭疏。","长揖去田庐。","囊无上赐金堪散，也未妨、山猎溪渔。","廉颇纵强，莫随年少，白马向黄榆。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.4000.json#record-201","tags":[]},{"id":"poem-4b1af59974526a5d13b6d8da","title":"临江仙·谢家仙观寄云岑","author":"牛希济","dynasty":"五代","verses":["谢家仙观寄云岑，岩萝拂地成阴。","洞房不闭白云深，当时丹灶，一粒化黄金。","石壁霞衣犹半挂，松风长似鸣琴。","时间唳鹤起前林，十洲高会，何处许相寻？"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-5-juan.json#record-34","tags":[]},{"id":"poem-4b1d2ab3d01db64d20e751e2","title":"寓居临平山下三首 其三","author":"张祜","dynasty":"唐","verses":["散髪垂肩久不簪，竹床推椀就藤阴。","涧傍春渡水流急，山半夜归云色深。","拂槛数竿为去处，随波一叶是浮沉。","世间年少正行乐，应笑老人无事心。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-afdf02f9-0d3e-4bd2-8eb1-9c2cb8694c10","tags":[]},{"id":"poem-4b23ce3baa7721f9692bbb0e","title":"梁谿八咏 文会堂","author":"李纲","dynasty":"宋","verses":["亲宾情话款衡门，把酒挥毫气吐云。","何日寛思返三径，一樽重与细论文。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.90000.json#record-a6eef792-d7b8-4f65-9d5c-722b122caab2","tags":[]},{"id":"poem-4b29c193eb2149dd3dbaa3ad","title":"玉胡蝶・玉蝴蝶·晚雨未摧宫树","author":"史达祖","dynasty":"宋","verses":["晚雨未摧宫树，可怜闲叶，犹抱凉蝉。","短景归秋，吟思又接愁边。","漏初长、梦魂难禁，人渐老、风月俱寒。","想幽欢。","土花庭，虫网阑干。","无端。","啼蛄搅夜，恨随团扇，苦近秋莲。","一笛当楼，谢娘悬泪立风前。","故园晚、强留诗酒，新雁远、不致寒暄。","隔苍烟。","楚香罗袖，谁伴婵娟。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-185","tags":["宋词三百首"]},{"id":"poem-4b2b1e34172bd1a6e45709e2","title":"题山院","author":"权审","dynasty":"唐","verses":["万叶风声利，一山秋气寒。","晓霜浮碧瓦，落日度朱栏。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-3c64bb3c-68fd-4dc0-8830-3c319892b3a2","tags":[]},{"id":"poem-4b2d8f274534bb9534dc5d72","title":"六三","author":"王梵志","dynasty":"唐","verses":["双陆智人戏，园碁出专能。","（「园」，伯三六五六卷作「围」。","）解时终不恶，（「时」，斯三三九三卷作「事」。","）久后与仙通。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-65c41b95-5ceb-417b-ad6e-18b8b601311e","tags":[]},{"id":"poem-4b31cf9174af7b0a522576ad","title":"禅社首乐章","author":"源乾曜","dynasty":"唐","verses":["灵具醉，杳熙熙。","灵将往，眇禗禗。","愿明德，吐正词。","烂遗光，流祯祺。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-2caf55bd-0b7a-475d-bfb6-d415d09bf010","tags":[]},{"id":"poem-4b349dc7037abf2785946d25","title":"段秀才溪居送从弟游泾陇","author":"李洞","dynasty":"唐","verses":["抱疾寒溪卧，因循草木青。","相留开夏蜜，辞去见秋萤。","朔雪痕侵雍，边烽焰照泾。","烟沈陇山色，西望涕交零。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-8e75e0fc-0852-401a-9f09-4365e037e481","tags":[]},{"id":"poem-4b441eecabeb9b01692a9d16","title":"游南岳","author":"张乔","dynasty":"唐","verses":["入岩仙境清，行尽复重行。","若得闲无事，长来寄此生。","涧松闲易老，笼烛晚生明。","一宿泉声里，思乡梦不成。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-3805cb81-114a-40ca-8eb5-028c0c9d0165","tags":[]},{"id":"poem-4b458c6ecc7f5fb3177a7a49","title":"梦李白二首 二","author":"杜甫","dynasty":"唐","verses":["浮云终日行，游子久不至。","三夜频梦君，情亲见君意。","告归常局促，苦道来不易。","江湖多风波，舟楫恐失坠。","出门搔白首，若负平生志。","冠盖满京华，斯人独顦顇。","孰云网恢恢，将老身反累。","千秋万岁名，寂莫身后事。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-0710a746-8660-4bc1-b073-8ce51ac9f4d9","tags":["唐诗三百首","友人","同情","记梦","五言古诗"]},{"id":"poem-4b4e7034df3bb9451efde6c7","title":"菩萨蛮·当时学舞钧天部","author":"毛滂","dynasty":"宋","verses":["当时学舞钧天部。","惊鸿吹下江湖去。","家住百花桥。","何郎偏与娇。","杏梁尘拂面。","牙板闻莺燕。","劝客玉梨花。","月侵钗燕斜。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.4000.json#record-871","tags":[]},{"id":"poem-4b53324e268d8d7caaa6a151","title":"朝中措·冻云著地静无风","author":"史浩","dynasty":"宋","verses":["冻云著地静无风。","簌蔌坠遥空。","无限人间险秽，一时为尔包容。","凭高试望，楼台改观，山径迷踪。","唯有碧江千里，依然不住流东。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.8000.json#record-132","tags":[]},{"id":"poem-4b534e05ff568c4ea32f3711","title":"酒泉子·敛态窗前","author":"孙光宪","dynasty":"五代","verses":["敛态窗前，袅袅雀钗抛颈。","燕成双，鸾对影，耦新知。","玉纤淡拂眉山小，镜中嗔共照。","翠连娟，红缥渺，早妆时。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-8-juan.json#record-18","tags":[]},{"id":"poem-4b576723e88b2b3ff87e8173","title":"雨霁登北岸寄友人","author":"卢殷","dynasty":"唐","verses":["稻黄扑扑黍油油，野树连山涧自流。","忆得年时冯翊部，谢郎相引上楼头。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-9cca0a6d-cc6b-4465-846b-5e3b4ff39470","tags":[]},{"id":"poem-4b5b878429cfa8890c2e8c5e","title":"古乐府 燕歌行","author":"张载","dynasty":"宋","verses":["小雅废兮，东山不作。","哀我人斯，皇心不乐。","烝哉斯人，胡然而天兮，王师于铄。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.30000.json#record-5a0cfe2b-546b-4d62-959c-5481d4603d4a","tags":[]},{"id":"poem-4b62673527b253235558254b","title":"感怀呈所知","author":"谭用之","dynasty":"宋","verses":["十年流落赋归鸿，谁傍昏衢驾烛龙。","竹屋乱烟思梓泽，酒家疏雨梦临邛。","千年别恨调琴懒，一片年光览镜慵。","早晚休歌白石烂，放教归去卧群峰。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.0.json#record-1b64fbfe-a1ea-4463-ab21-357c23f51dbe","tags":[]},{"id":"poem-4b74e14c620e481365bbf3ed","title":"寄弟","author":"吕从庆","dynasty":"唐","verses":["函罢家音又拆看，添书绝句报平安。","丰溪渔叟生涯定，明月清风一钓竿。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-01200a90-c853-442b-9718-e331b49a883f","tags":[]},{"id":"poem-4b81fa9275c4c0aa13044689","title":"赠索处士","author":"谭用之","dynasty":"宋","verses":["不将桂子种诸天，长得寻君水石边。","玄豹夜寒和雾隠，骊龙春暖抱珠眠。","山中宰相陶弘景，洞里真人葛稚川。","一度相思一惆怅，水寒烟澹落花前。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.0.json#record-02fe3269-0f06-4b1d-826e-1f9f2617bc93","tags":[]},{"id":"poem-4b8207910b0e10f349adf020","title":"泊秦淮","author":"杜牧","dynasty":"唐","verses":["烟笼寒水月笼沙，夜泊秦淮近酒家。","商女不知亡国恨，隔江犹唱后庭花。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-8de30193-fba7-4aef-9ff9-c3726a22104d","tags":["唐诗三百首","隋・唐・五代","爱国","写景","初中古诗","七言绝句","抒怀","咏史怀古","七年级上册(课外)"]},{"id":"poem-4b8b85e0469ef0a7f1aee3c4","title":"酬沈先辈卷","author":"归仁","dynasty":"唐","verses":["一百八十首，清泠韵可敲。","任从人不爱，终是我难抛。","桂魄吟来满，蒲团坐得凹。","先生声价在，寰宇几人抄。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-54e63514-fd37-4d2c-bc84-cdd9bdf10efe","tags":[]},{"id":"poem-4b963464db918ce54e57cab0","title":"醉落魄・一斛珠·陶陶兀兀","author":"黄庭坚","dynasty":"宋","verses":["陶陶兀兀。","人生无累何由得。","杯中三万六千日。","闷损旁观，自我解落魄。","扶头不起还颓玉。","日高春睡平生足。","谁门可款新𥬠熟。","安乐春泉，玉醴荔枝绿。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.2000.json#record-709","tags":[]},{"id":"poem-4b9db80d8f66d4b0b968a85f","title":"兵要望江南 占六壬第二十八（京本列第十七○四十五首） 二十八","author":"易静","dynasty":"唐","verses":["荧惑煞，只是丙丁神。","加在金方兵已退，亦无征战不伤人，发动愈重迍（京本作「日与喜神亲」）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-79f6f315-92d9-4065-82ee-80fb707c65fc","tags":[]},{"id":"poem-4ba62326b4c8646c4751ce21","title":"咏史诗 洛阳","author":"胡曾","dynasty":"唐","verses":["石勒童年有战机，洛阳长啸倚门时。","晋朝不是王夷甫，大智何由得预知。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-3c2a658e-428f-4c4f-b5bc-bceaae855db7","tags":[]},{"id":"poem-4ba67d85edbb9dfdd65d2b2d","title":"望海潮·人间花老","author":"晁补之","dynasty":"宋","verses":["人间花老，天涯春去，扬州别是风光。","红药万株，佳名千种，天然浩态狂香。","尊贵御衣黄。","未便教西洛，独占花王。","困倚东风，汉宫谁敢斗新妆。","年年高会维阳。","看家夸绝艳，人诧奇芳。","结蕊当屏，联葩就幄，红遮绿绕华堂。","花面映交相。","更秉菅观洧，幽意难忘。","罢酒风亭，梦魂惊恐在仙乡。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.4000.json#record-160","tags":[]},{"id":"poem-4ba8dc1ac13f4f7d4ef1049a","title":"驯鹤图","author":"王予可","dynasty":"宋","verses":["寝处粧铅未卷钗，孤云花带月边来。","六宫帘幕金鸾冷，露湿晨烟啄翠苔。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.120000.json#record-0c09c1ff-d213-4779-a4cc-2ca7e4eaec13","tags":[]},{"id":"poem-4bab746d72d3cc723068fd34","title":"汝坟","author":"佚名","dynasty":"先秦","verses":["遵彼汝坟，伐其条枚。未见君子，惄如调饥。","遵彼汝坟，伐其条肄。既见君子，不我遐弃。","鲂鱼赪尾，王室如毁。虽则如毁，父母孔迩。"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-9","tags":[]},{"id":"poem-4baddf97d21bfc2c6621b644","title":"眼儿媚·独倚春寒掩夕扉","author":"纳兰性德","dynasty":"清","verses":["独倚春寒掩夕扉，清露泣铢衣。","玉萧吹梦，金钗划影，悔不同携。","刻残红烛曾相待，旧事总依稀。","料应遗恨，月中教去，花底催归。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-37","tags":[]},{"id":"poem-4bb108f060d543847487a382","title":"蝶恋花·寒雨霏霏江上路","author":"王之道","dynasty":"宋","verses":["寒雨霏霏江上路。","不见书邮，病目空凝注。","沙觜尽头飞白鹭。","篙师指似人来处。","自笑自怜还自语。","钝滞如君，只合归田去。","竹屋数间环甽亩。","个中自有无穷趣。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.6000.json#record-131","tags":[]},{"id":"poem-4bb7bf5b75293b3cb2331cfb","title":"逢故人","author":"张籍","dynasty":"唐","verses":["山东一十余年别，今日相逢在上都。","说尽向来无限事，相看摩捋白髭须。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-dbd2b5f0-bdcd-4cf6-a824-32cdc7ed6eaf","tags":[]},{"id":"poem-4bba7153af54a1d479c311f4","title":"望江南・忆江南·新月出","author":"李纲","dynasty":"宋","verses":["新月出，清影尚苍茫。","学扇欲生青海上，如钩先挂碧霄傍。","星斗焕文章。","林下客，把酒挹孤光。","斟酌嫦娥怜我老，故窥书幌照人床。","此意自难忘。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.6000.json#record-566","tags":[]},{"id":"poem-4bc378a975b5d76de1facda6","title":"句","author":"殷穆","dynasty":"唐","verses":["藤拂石溪流水净，风来云寺过钟微。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-4d46e4f1-5c3a-436a-b376-7bacb9f4cdf9","tags":[]},{"id":"poem-4bd4cd29f29983ceba9030be","title":"哭胡处士","author":"曹松","dynasty":"唐","verses":["故人江阁在，重到事悠悠。","无尔向潭上，为吾倾瓮头。","空余赤枫叶，堕落钓鱼舟。","疑是冲虚去，不为天地囚。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-393346d5-2332-4d13-82f6-09fcaf1798f2","tags":[]},{"id":"poem-4bd8ce38e7baadfaa53d11fe","title":"盛山十二诗 绣衣石榻","author":"韦处厚","dynasty":"唐","verses":["巉巉雪中峤，磊磊标方峭。","勿为枕苍山，还当础清庙。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-78a5f66c-fe4e-475d-b9a3-ba41688cbdcf","tags":[]},{"id":"poem-4bdd4c1453619f5053ecc34c","title":"梧桐树","author":"徐田臣《杀狗记》","dynasty":"元","verses":["(丑)官人听我言：世事只如此。","只重衣衫，那重人贤慧！如今只重钱和势，你恁贫寒识甚高低？一领布衫，比不得咱每的？何须共你争闲气！。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-1848","tags":[]},{"id":"poem-4bdd8c26c0b8bfbf6cbd4af0","title":"送梓州李使君","author":"王维","dynasty":"唐","verses":["万壑树参天，千山响杜鹃。","山中一夜雨，树杪百重泉。","汉女输橦布，巴人讼芋田。","文翁翻教授，不敢倚先贤。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-263b4a33-fd51-47e1-b49a-d84dd99a2e0f","tags":["唐诗三百首","友情","送别","五言律诗"]},{"id":"poem-4be4296e5f9e881c715c1d20","title":"唐大飨拜洛乐章 通和","author":"则天皇后","dynasty":"唐","verses":["皇皇灵睠，穆穆神心。","暂动凝质，还归积阴。","功玄枢纽，理寂高深。","衔恩佩德，耸志翘襟。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-8ee6bcb7-cb08-467c-91bd-ece8e555228c","tags":[]},{"id":"poem-4be92e7ce5d07a85672b1dc0","title":"小重山·枕上阊门五报更","author":"贺铸","dynasty":"宋","verses":["枕上阊门五报更。","蜡灯香灺冷，恨天明。","青苹风转彩帆轻。","樯头燕，多谢伴人行。","临镜想倾城。","两尖愁黛浅，泪波横。","艳歌重记遣离情。","缠绵处，翻是断肠声。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.4000.json#record-0","tags":[]},{"id":"poem-4c03af5c4d3bb0d3b1aec4c4","title":"同前","author":"萧德祥《小孙屠》","dynasty":"元","verses":["哀告君听：奴在房儿卫欲睡寝？怎知叔叔来此，巧言花语，扯奴衣襟。","(末白)孙二须不是这般样人。","(旦连唱)因奴家不肯便生嗔，将刀欲害伊家命。","(末白)哥哥休听它家说，孙二不敢。","(旦连唱)只得叫邻人，将奴赶得没投奔。","(生)。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-8625","tags":[]},{"id":"poem-4c03fab7dd597843f7067f94","title":"送鄂渚秋官陈伯奇兼柬阮广文","author":"释居简","dynasty":"宋","verses":["荣如李郭舟，小为蜀僧留。","江汉渺何许，琴书占上游。","贪程人易别，劳劝酒难酬。","黄鹤风烟古，何曾怕搅搜。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.180000.json#record-c838945a-684d-4f9c-b548-83b845e9884d","tags":[]},{"id":"poem-4c0605e60f4aa5a1725f62ac","title":"句  其四","author":"杨徽之","dynasty":"宋","verses":["废宅寒塘水，荒坟宿草烟。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.0.json#record-e7c47a3e-22ac-4162-9405-b2b0c7a86740","tags":[]},{"id":"poem-4c0798920e0b1b8a2d70d417","title":"失调名·教我甚情怀","author":"李清照","dynasty":"宋","verses":["教我甚情怀。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.6000.json#record-719","tags":[]},{"id":"poem-4c07ffb4a3027bde90373486","title":"送程秀才下第归蜀","author":"姚鹄","dynasty":"唐","verses":["莺迁与鶂退，十载泣岐分。","蜀道重来老，巴猨此去闻。","晓程侵岭雪，远栈入谿云。","莫滞趋庭恋，荣亲祗待君。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-e6503dc8-2d00-4ee0-a3cd-dc55313bd97d","tags":[]},{"id":"poem-4c0851758cfa5fb4beb4c59c","title":"烛影摇红·霭霭春空","author":"廖世美","dynasty":"宋","verses":["霭霭春空，画楼森耸凌云渚。","紫薇登览最关情，绝妙夸能赋。","惆怅相思迟暮。","记当日、朱阑共语。","塞鸿难问，岸柳何穷，别愁纷絮。","催促年光，旧来流水知何处。","断肠何必更残阳，极目伤平楚。","晚霁波声带雨。","悄无人、舟横野渡。","数峰江上，芳草天涯，参差烟树。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-199","tags":["宋词三百首"]},{"id":"poem-4c0dbdc4be3b88fafeca276b","title":"郊庙歌辞 武后明堂乐章 皇嗣出入升降","author":"武则天","dynasty":"唐","verses":["至人光俗，大孝通神。","谦以表性，恭惟立身。","洪规载启，茂典方陈。","誉隆三善，祥开万春。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-f9975b6c-83a5-4d7d-be29-ae59be144e35","tags":[]},{"id":"poem-4c160e3f80f51260b800c2b2","title":"送毛伯温","author":"明世宗","dynasty":"明","verses":["大将南征胆气豪，腰横秋水雁翎刀。","风吹鼍鼓山河动，电闪旌旗日月高。","天上麒麟原有种，穴中蝼蚁岂能逃。","太平待诏归来日，朕与先生解战袍。"],"enabled":true,"collection":"千家诗","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/蒙学/qianjiashi.json#record-送毛伯溫","tags":[]},{"id":"poem-4c1a9129ac1f8d28f009f25a","title":"关山月","author":"李咸用","dynasty":"唐","verses":["离离天际云，皎皎关山月。","羌笛一声来，白尽征人髪。","嘹唳孤鸿高，萧索悲风发。","雪压塞尘清，雕落沙场阔。","何当胡无人，荷戈朝凤阙。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-797e6674-d389-4f87-bdfb-50861c154abe","tags":[]},{"id":"poem-4c24a0a70cc1022117070531","title":"题温泉","author":"李涉","dynasty":"唐","verses":["能使时平四十春，开元圣主得贤臣。","当时姚宋幷燕许，尽是骊山从驾人。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-aef512bc-1c46-4b17-8a03-a7fe50f5ad25","tags":[]},{"id":"poem-4c259028","title":"咏怀·其一","author":"阮籍","dynasty":"魏","verses":["夜中不能寐，起坐弹鸣琴。","薄帷鉴明月，清风吹我襟。","孤鸿号外野，翔鸟鸣北林。","徘徊将何见？忧思独伤心。"],"enabled":true,"collection":"历代名篇","source":"《阮嗣宗集》诗《咏怀八十二首》其一。","tags":["抒怀"]},{"id":"poem-4c26613cbcf216cf32285556","title":"谢宣城朱长官","author":"释居简","dynasty":"宋","verses":["飞来何处山，秀整连凤池。","绝胜一鉏地，天地不得私。","朣朣斗牛间，明玉生华滋。","凛姿岁寒后，萧洒观孙枝。","出宰山水县，小谢城东陲。","琴瑟日在御，箠楚不苟施。","春风河阳花，次第芳菲菲。","屈指九十日，日日把酒巵。","玉山不须扶，百里皆酣嘻。","行扳星辰履，颉颃丛霄蜚。","故家厚培㙲，衮绣看传衣。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.180000.json#record-19e9d1ab-1419-409e-8e65-604fcabfe843","tags":[]},{"id":"poem-4c27205f4eb7c7161ac8feb4","title":"苏小小墓","author":"王镃","dynasty":"宋","verses":["同心难结绣云长，红玉沉泥草亦香。","娇魄年年寒食节，定应湖上作鸳鸯。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.240000.json#record-4a7bb04a-1981-4826-98ea-6a687b69af95","tags":[]},{"id":"poem-4c2760413c5212177365f776","title":"自苏台至望亭驿人家尽空春物增思怅然有作因寄从弟纾","author":"李嘉祐","dynasty":"唐","verses":["南浦菰蒋覆白苹，东吴黎庶逐黄巾。","野棠自发空临水，江燕初归不见人。","远岫依依如送客，平田渺渺独伤春。","那堪回首长洲苑，烽火年年报虏尘。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-39623e50-e397-46d0-8715-f405674194cf","tags":[]},{"id":"poem-4c3b90a61b9f6652b3f71550","title":"兵要望江南 太乙式第二十七（本门中「太乙」二字，辛本、川本皆作「天乙」○三十一首） 二十","author":"易静","dynasty":"唐","verses":["子符使，都忌在三宫。","戌怕冲（辛本、川本作「坤」）宫申在艮，午离酉巽必为凶，寅与甲辰同。","。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-02108b88-b2ca-43f2-adc9-b5f354e024dd","tags":[]},{"id":"poem-4c3e23c2247dd97054f63ec2","title":"投韩员外六韵","author":"张祜","dynasty":"唐","verses":["见说韩员外，声华溢九垓。","大川舟欲济，荒草路初开。","耸地千浔壁，（「千浔」，疑应作「千寻」。","）森云百丈材。","狂波心上涌，骤雨笔前来。","后学无人誉，先贤亦自媒。","还闻孔融表，曾荐祢衡才。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-6e1b8a95-ee7c-465b-b0c0-d2e16a9242eb","tags":[]},{"id":"poem-4c44e0e9385a7f83355b58ee","title":"遗诗 一","author":"卢道者","dynasty":"唐","verses":["三十年前卖卜，化得一间茅屋。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-72df84c1-042d-480f-9c3b-3893217d0ae1","tags":[]},{"id":"poem-4c4baa780b5aa989b075aa50","title":"次韵和复古春日五绝句  其一","author":"司马光","dynasty":"宋","verses":["雪霜哀鬓拔还生，桃李新园长未成。","五十尚能胜六十，今年又灭去年情。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.30000.json#record-d904bb79-c49f-4944-b9b9-057d3123480e","tags":[]},{"id":"poem-4c50e73265a1885169f40961","title":"所居即事六首（原注：丹阳闲居寄郑明府如范上人。） 其四（原注：春日寓言。）","author":"张祜","dynasty":"唐","verses":["寂寞春风意未降，酒狂诗癖旧无双。","柳花飞处曾逢雪，桃叶开提忆渡江。","自古不堪居陋巷，从今休更犯危邦。","圣朝何用询名姓，从放书生老北窗。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-eca96d99-534b-4d9f-865a-944e3e79e8ea","tags":[]},{"id":"poem-4c51374f0b5c2d1e5f04f31d","title":"其日雨中闻姚黄开戏成诗二章呈子骏尧夫  其一","author":"司马光","dynasty":"宋","verses":["谷雨后来花更浓，前时已是玉玲珑。","客来更说姚黄发，只在街西相第东。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.30000.json#record-327b8722-6cde-49a8-86c7-24e0ce2b294a","tags":[]},{"id":"poem-4c58d1e7782739f59c1deaf2","title":"湖上","author":"王同祖","dynasty":"宋","verses":["湖头春水千丈碧，湖堤袅柳不盈尺。","唱歌女儿棹船回，惊起沙鸥对对立。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.210000.json#record-81d8c5aa-a7b8-4384-ad4d-5c6034800d31","tags":[]},{"id":"poem-4c5bc4c20b31bd5d7e7f6417","title":"苏端薛复筵简薛华醉歌","author":"杜甫","dynasty":"唐","verses":["文章有神交有道，端复得之名誉早。","爱客满堂尽豪翰，开筵上日思芳草。","安得健步移远梅，乱插繁花向晴昊。","千里犹残旧冰雪，百壶且试开怀抱。","垂老恶闻战鼓悲，急觞为缓忧心捣。","少年努力纵谈笑，看我形容已枯槁。","坐中薛华善醉歌，歌辞自作风格老。","近来海内为长句，汝与山东李白好。","何刘沈谢力未工，才兼鲍昭愁绝倒。","诸生颇尽新知乐，万事终伤不自保。","气酣日落西风来，愿吹野水添金杯。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-e848498b-1ab8-48c7-8b3e-e98b5550b855","tags":[]},{"id":"poem-4c5f70d86a8aaad51afcfc5e","title":"和程员外春日东郊即事","author":"包何","dynasty":"唐","verses":["郎官休浣怜迟日，野老欢娱为有年。","几处折花惊蝶梦，数家留叶待蚕眠。","藤垂宛地萦珠履，泉迸侵堦浸绿钱。","直到闭关朝谒去，莺声不散柳含烟。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-6dbed00f-b5d4-4276-8de1-d65054b3d4a7","tags":[]},{"id":"poem-4c6d83dae8a383994cd20556","title":"和元宗元日大雪登楼","author":"徐铉","dynasty":"宋","verses":["一宿东林正气和，便随仙仗放春华。","散飘白絮惟分影，轻缀青旗始见花。","落砌更依宫舞转，入楼偏向御衣斜。","严徐共待金门诏，愿布尧言贺万家。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.0.json#record-f761e78a-66fd-4965-867c-cf9c345f3454","tags":[]},{"id":"poem-4c792cba87235164dce501ad","title":"和常州崔使君咏后庭梅二首 二","author":"孙逖","dynasty":"唐","verses":["梅院重门掩，遥遥歌吹边。","庭深人不见，春至曲能传。","花落弹棋处，香来荐枕前。","使君停五马，行乐此中偏。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-0f9fd0ad-8527-4d0a-8ad1-c8c07c0a8131","tags":[]},{"id":"poem-4c8b7aa20cbc021b1a6bad0b","title":"太子张舍人遗织成褥段","author":"杜甫","dynasty":"唐","verses":["客从西北来，遗我翠织成。","开缄风涛涌，中有掉尾鲸。","逶迤罗水族，琐细不足名。","客云充君褥，承君终宴荣。","空堂魑魅走，高枕形神清。","领客珍重意，顾我非公卿。","留之惧不祥，施之混柴荆。","服饰定尊卑，大哉万古程。","今我一贱老，裋褐更无营。","煌煌珠宫物，寝处祸所婴。","叹息当路子，干戈尚纵横。","掌握有权柄，衣马自肥轻。","李鼎死岐阳，实以骄贵盈。","来瑱赐自尽，气豪直阻兵。","皆闻黄金多，坐见悔吝生。","奈何田舍翁，受此厚贶情。","锦鲸卷还客，始觉心和平。","振我麤席尘，媿客茹藜羹。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-3e025699-a493-49b3-8b9d-be47fd65a2ae","tags":[]},{"id":"poem-4c9961cdb0bac806ba2f05da","title":"题灵泉寺","author":"徐源","dynasty":"唐","verses":["竹园无外事，秘殿夕阴生。","云起灵峰隐，风来宝铎鸣。","焚香流玉户，听鸟度金楹。","静心归正法，方此谢尘缨。","（见武虚谷《安阳县金石录》。","）（诗下原题「高平徐源字太初」七字。","又纪「皇唐八叶大历六年岁次辛亥夏四月旬有五日」十九字。","）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-a7992a5c-e098-4e29-a5e3-fc469f3a5127","tags":[]},{"id":"poem-4c9a98218690aa1e2e7ac600","title":"仙吕/赏花时","author":"杨景贤","dynasty":"元","verses":["一纸书缄万种愁，数日忧成两鬓秋。","疾忙去莫迟留，休误了鸾交凤友，且跳过短墙头。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-4493","tags":[]},{"id":"poem-4ca515a5a6a23e0337094ef0","title":"马上见卖白莲者三首  其二","author":"陈造","dynasty":"宋","verses":["东荡百顷宽，满荡莲结花。","孤村莲荡西，茅茨吾所家。","年年红紫尽，为春留芳华。","酒船堕云锦，歌棹凌瑞霞。","只今乡闾梦，不道身风沙。","把花但三嗅，对酒长咨嗟。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.150000.json#record-d8416900-fa25-4323-8dc2-5ae3c293f810","tags":[]},{"id":"poem-4ca67b11f2aa5b6ad1f41e21","title":"句","author":"张牙","dynasty":"唐","verses":["看看舞罢轻云去，应赴襄王梦里期。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-97e0ea68-3531-4203-9a23-9c2971612d63","tags":[]},{"id":"poem-4ca952a2eade6de84e4b9ea1","title":"鄠郊山舍题赵处士林亭","author":"李洞","dynasty":"唐","verses":["圭峰秋后叠，乱叶落寒墟。","四五百竿竹，二三千卷书。","云深猿拾栗，雨霁蚁缘蔬。","只隔门前水，如同万里余。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-82ae295e-360d-4e4e-be5a-1ed9f27e7cd7","tags":[]},{"id":"poem-4cb366f606d11a5e2260f269","title":"玄鸟","author":"佚名","dynasty":"先秦","verses":["天命玄鸟，降而生商，宅殷土芒芒。古帝命武汤，正域彼四方。","方命厥后，奄有九有。商之先后，受命不殆，在武丁孙子。武丁孙子，武王靡不胜。","龙旗十乘，大糦是承。邦畿千里，维民所止，肇域彼四海。","四海来假，来假祁祁。景员维河。殷受命咸宜，百禄是何。"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-302","tags":[]},{"id":"poem-4cc40227e0e4526dcaea4377","title":"·","author":"李鹗","dynasty":"唐","verses":["。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-681d6234-a3f7-460e-ace7-c1c7ce662677","tags":[]},{"id":"poem-4ccb08c9c67b7a136c6057ed","title":"江行无题一百首 六十四","author":"钱珝","dynasty":"唐","verses":["白帝朝惊浪，阳台暮映云。","等闲生险易，世路秪如君。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-ec9688a6-6ed2-48f7-bcee-82e31ff33b58","tags":[]},{"id":"poem-4cce86f0ededf871c94f9ff6","title":"定西番·帝子枕前秋夜","author":"孙光宪","dynasty":"五代","verses":["帝子枕前秋夜，霜幄冷，月华明，正三更。","何处戍楼寒笛，梦残闻一声。","遥想汉关万里，泪纵横。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-8-juan.json#record-29","tags":[]},{"id":"poem-4cdc2ed8878051ecb1da4849","title":"题止戈堂二首奉呈安抚程待制  其一","author":"李纲","dynasty":"宋","verses":["会府繁雄冠列城，恩颁符节付名卿。","貔貅战罢烽烟息，豺虎销除氛祲清。","齐阁已闻铃索静，提封更绝羽书惊。","止戈当自瓯闽始，愿挽天河洗甲兵。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.90000.json#record-4e6824be-c631-48f6-b835-615037c3a9f0","tags":[]},{"id":"poem-4cdd9bc568cb1a0826701a44","title":"题落叶","author":"司空曙","dynasty":"唐","verses":["霜景催危叶，今朝半树空。","萧条故国异，零落旅人同。","飒岸浮寒水，依堦拥夜虫。","随风偏可羡，得到洛阳宫。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-35638e63-ef59-411d-a832-af24221fd0fd","tags":[]},{"id":"poem-4ce59bb13d52aa84cf0c5d11","title":"阮郎归·小舟载酒向平湖","author":"米友仁","dynasty":"宋","verses":["小舟载酒向平湖。","新凉生晓初。","乱山烟外有还无。","王维真画图。","风遽起，动襟裾。","雨来荷溅珠。","一尊相对喜君俱。","醉归红袖扶。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.2000.json#record-52","tags":[]},{"id":"poem-4cf2409c45bab7922510a7c0","title":"游仙词三十三首  其四","author":"王镃","dynasty":"宋","verses":["月斜天路晓风清，缥缈云开见玉城。","无数小仙参阙罢，相逢只是说长生。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.240000.json#record-fdb71c51-6fb8-421f-9a20-132c383984ec","tags":[]},{"id":"poem-4cf2ee824b703af511b67a71","title":"卜算子·风生杜若洲","author":"张孝祥","dynasty":"宋","verses":["风生杜若洲，日暮垂杨浦。","行到田田乱叶边，不见凌波女。","独自倚危栏，欲向荷花语。","无奈荷花不应人，背立啼红雨。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.2000.json#record-384","tags":[]},{"id":"poem-4cf47248b4c65532cfed2dd7","title":"盛山十二诗 竹岩","author":"韦处厚","dynasty":"唐","verses":["不资冬日秀，为作暑天寒。","先植诚非凤，来翔定是鸾。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-ddadb644-49a7-452c-8ce3-85ebd55de76f","tags":[]},{"id":"poem-4cf48d8afb99df1f5a320dcc","title":"前腔","author":"施惠《幽闺记》","dynasty":"元","verses":["(生)闷可消除，只怕醉倒黄公旧酒垆。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-2979","tags":[]},{"id":"poem-4cfb91564dfb7684f37440d2","title":"沔水","author":"佚名","dynasty":"先秦","verses":["沔彼流水，朝宗于海。𫛣彼飞隼，载飞载止。嗟我兄弟，邦人诸友。莫肯念乱，谁无父母？","沔彼流水，其流汤汤。𫛣彼飞隼，载飞载扬。念彼不迹，载起载行。心之忧矣，不可弭忘。","𫛣彼飞隼，率彼中陵。民之讹言，宁莫之惩？我友敬矣，谗言其兴。"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-182","tags":[]},{"id":"poem-4cfbbaa4b1b3c294ba292fa3","title":"前腔","author":"施惠《幽闺记》","dynasty":"元","verses":["(生、旦)苦不苦。","从头至足，衣衫皆褴褛。","难同他往来客旅。","(众)你不与，我施威仗勇，轮动刀和斧。","激得人忿心发怒。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-2958","tags":[]},{"id":"poem-4cfe3cb6a7f9005cee7d3e0c","title":"却望无锡芙蓉湖 四","author":"李绅","dynasty":"唐","verses":["旧山认得烟岚近，湖水平铺碧岫间。","喜见云泉还怅望，自慙山叟不归山。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-b38832ba-1187-4a67-8cf1-dcf8bc6337e2","tags":[]},{"id":"poem-4cff47716c2c4b1f5cc7bec3","title":"八月十五夜赠张功曹","author":"韩愈","dynasty":"唐","verses":["纤云四卷天无河，清风吹空月舒波。","沙平水息声影绝，一桮相属君当歌。","君歌声酸辞且苦，不能听终泪如雨。","洞庭连天九疑高，蛟龙出没猩鼯号。","十生九死到官所，幽居默默如藏逃。","下床畏蛇食畏药，海气湿蛰熏腥臊。","昨者州前搥大鼓，嗣皇继圣登夔臯。","赦书一日行万里，罪从大辟皆除死。","迁者追廻流者还，涤瑕荡垢清朝班。","州家申名使家抑，坎轲祗得移荆蛮。","判司卑官不堪说，未免捶楚尘埃间。","同时辈流多上道，天路幽险难追攀。","君歌且休听我歌，我歌今与君殊科。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-88e98bed-27fa-4dbe-8d6e-e7cb8c3e4d97","tags":["唐诗三百首","洞庭湖","中秋节","七言古诗","抒怀","饮酒"]},{"id":"poem-4cff833b0618469c4c7cdfb0","title":"西溪独泛","author":"皎然","dynasty":"唐","verses":["道情何所居，素舸漫流间。","真性怜高鹤，无名羡野山。","经寒丛竹秀，入静片云闲。","泛泛谁为侣，唯应共月还。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-c2ed6f9c-5526-4c32-9bc0-bc8f3d272fdb","tags":[]},{"id":"poem-4d05a20f1ad57dd51c5887a5","title":"感遇十二首 四","author":"张九龄","dynasty":"唐","verses":["孤鸿海上来，池潢不敢顾。","侧见双翠鸟，巢在三珠树。","矫矫珍木巅，得无金丸惧。","美服患人指，高明逼神恶。","今我游冥冥，弋者何所慕。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-f9798830-48c1-45e3-be90-4028d93954dc","tags":["唐诗三百首","寓人","五言古诗","生活","哲理","抒怀","写鸟","鸟"]},{"id":"poem-4d112038ab8bafa245b070c9","title":"酒泉子·闲卧绣纬","author":"毛熙震","dynasty":"五代","verses":["闲卧绣纬，慵想万般情宠。","锦檀偏，翘股重，翠云欹。","暮天屏上春山碧，映香烟雾隔。","蕙兰心，魂梦役，敛蛾眉。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-x-juan.json#record-8","tags":[]},{"id":"poem-4d158dd675b65521db60bcc3","title":"偈颂 四","author":"文偃","dynasty":"唐","verses":["是机是对对机迷，辟机（一作「尘」）尘远远机（《僧宝传》卷二作「尘」）栖。","夕日日中谁有挂，因底底事隔情（《僧宝传》作「尘」）迷。","。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-60918b7c-cb83-44ae-bbab-9a6732b1a956","tags":[]},{"id":"poem-4d19dadf15b59cb695e8ac72","title":"病马五首呈郑校书章三吴十五先辈 四","author":"曹唐","dynasty":"唐","verses":["空被秋风吹病毛，无因濯浪刷洪涛。","卧来总怪龙蹄跙，瘦尽谁惊虎口高。","追电有心犹欵段，逢人相骨强嘶号。","欲将鬐鬣重裁剪，乞借新成利铰刀。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-d40daf0a-349c-428f-a8d5-d292ca483ef2","tags":[]},{"id":"poem-4d219ca73ff806ee39539e83","title":"采桑子·蝤蛴领上诃梨子","author":"和凝","dynasty":"五代","verses":["蝤蛴领上诃梨子，绣带双垂，椒户闲时，竞学樗蒲赌荔枝。","丛头鞋子红编细，裙窣金丝。","无事颦眉，春思翻教阿母疑。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-6-juan.json#record-28","tags":[]},{"id":"poem-4d22a83b8f2d0122b8dc0ba3","title":"莺出谷","author":"钱可复","dynasty":"唐","verses":["玉律阳和变，时禽羽翮新。","载飞初出谷，一啭已惊人。","拂柳宜烟暖，冲花觉露春。","抟风翻翰疾，向日弄吭频。","求友心何切，迁乔幸有因。","华林高玉树，栖托及芳晨。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-cf7c54f7-8454-4621-bafd-e6096ae38434","tags":[]},{"id":"poem-4d2aeb8db2f106e3c05b45e4","title":"陪颜使君饯宣谕萧常侍","author":"皎然","dynasty":"唐","verses":["江涛凋瘵后，远使发天都。","昏垫宸心及，哀矜诏命敷。","恤民驱急传，访旧枉征舻。","外镇藩条最，中朝顾问殊。","文皆正风俗，名共溢寰区。","已事方怀阙，归期早戒涂。","繁笳咽水阁，高盖拥云衢。","暮色生千嶂，秋声入五湖。","离歌犹宛转，归驭已踟躇。","今夕庾公意，西楼月亦孤。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-512e5fd2-e9ca-4ee1-999c-e3e1e0862758","tags":[]},{"id":"poem-4d36ea1b97d795b226e746e6","title":"满庭芳·五十七年","author":"王以宁","dynasty":"宋","verses":["五十七年，侵寻老矣，小庵初筑林坰。","故人相过，喜雪舞祥霙。","遍野跳珠浅玉，纵儿童、收满金瓶。","明年待，洗光银海，袖手看升平。","先生。","齐物久，蚁丘罢战，蜗角休征。","趁尊前身健，有酒须倾。","随分村歌社舞，何须问、武宿文星。","忘怀矣，未能忘酒，相与醉忘形。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.6000.json#record-61","tags":[]},{"id":"poem-4d3a4059e0978f2b58f6fbdf","title":"柳枝·雀桥初就咽银河","author":"和凝","dynasty":"五代","verses":["雀桥初就咽银河，今夜仙郎自姓和。","不是昔年攀桂树，岂能月里索嫦娥。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-6-juan.json#record-31","tags":[]},{"id":"poem-4d3dae188411280b4ccb3a23","title":"满江红·怒发冲冠","author":"岳飞","dynasty":"宋","verses":["怒发冲冠，凭阑处、潇潇雨歇。","抬望眼、仰天长啸，壮怀激烈。","三十功名尘与土，八千里路云和月。","莫等闲、白了少年头，空悲切。","靖康耻，犹未雪。","臣子恨，何时灭。","驾长车踏破，贺兰山缺。","壮志饥餐胡虏肉，笑谈渴饮匈奴血。","待从头、收拾旧山河，朝天阙。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-117","tags":["宋词三百首"]},{"id":"poem-4d42a0710afd48c615244a1c","title":"赵飞燕姊妹","author":"赵崇嶓","dynasty":"宋","verses":["甲帐初停燕子飞，小雏相趁共差池。","春风吹水粼粼长，又有披香博士知。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.210000.json#record-2ffd037f-71c9-42d5-8403-f52915fffe6d","tags":[]},{"id":"poem-4d474e950e12ce9f8fc94bda","title":"初夏睡起","author":"杨万里","dynasty":"宋","verses":["梅子流酸溅齿牙，芭蕉分绿上窗纱。","日长睡起无情思，闲看儿童捉柳花。"],"enabled":true,"collection":"千家诗","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/蒙学/qianjiashi.json#record-初夏睡起","tags":[]},{"id":"poem-4d5581e1ef4cda921ddec7cc","title":"句","author":"骆仲舒","dynasty":"唐","verses":["张鸿诗在楞伽峡，韩愈碑留燕喜亭。","（《舆地纪胜》卷九二《连州》。","）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-3051a42c-b9bd-4ea8-949c-d41281e00dc5","tags":[]},{"id":"poem-4d606f3ca6f1849d083baa82","title":"点绛唇","author":"高明《蔡伯喈琵琶记》","dynasty":"元","verses":["月淡星稀，建章宫里，千门晓。","御炉烟袅，隐隐鸣梢杳。","忽忆年时，问寝高堂早。","鸡鸣了，闷萦怀抱，此际愁多少！。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-5020","tags":[]},{"id":"poem-4d649314141541853d952fed","title":"和杨卿中秋月","author":"司马光","dynasty":"宋","verses":["秋气平分夜，沈阴乍散天。","窥林初淡薄，照席忽孤圆。","泠入诗毫健，光浮醉弁偏。","嘉宾勿轻去，桂影正姢姢。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.30000.json#record-157bad13-6ad7-4154-b35f-0afc69a6ffcc","tags":[]},{"id":"poem-4d6d936311b124d66ac19c26","title":"和吴仲庶寄李子仪","author":"苏颂","dynasty":"宋","verses":["五纪修戎好，重关四向开。","村郊纵牛马，战地长蒿莱。","过客朝连暮，征轺去复回。","元侯勤主礼，一一倒瓶罍。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.30000.json#record-30ab0c76-e667-4585-a1b2-3abf5b80f630","tags":[]},{"id":"poem-4d718ec5330c52aa7339f931","title":"北苑侍宴杂咏诗 水","author":"徐铉","dynasty":"宋","verses":["碧草垂低岸，东风起细波。","横汾从游宴，何谢到天河。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.0.json#record-4bb1d2ca-33ea-4745-adce-b0d561b38bb1","tags":[]},{"id":"poem-4d72062480d78108ce0134c5","title":"枉系二首 二","author":"沈佺期","dynasty":"唐","verses":["昔日公冶长，非罪遇缧絏。","圣人降其子，古来叹独绝。","我无毫髪瑕，苦心怀冰雪。","今代多秀士，谁能继明辙。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-312131ec-449f-405a-ac52-8a6b33845b17","tags":[]},{"id":"poem-4d7860d9e8dd2fafd3b996a6","title":"菩萨蛮·舞裙香暖金泥凤","author":"牛峤","dynasty":"五代","verses":["舞裙香暖金泥凤，画梁语燕惊残梦。","门外柳花飞，玉郎犹未归。","愁匀红粉泪，眉剪春山翠。","何处是辽阳，锦屏春昼长。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-4-juan.json#record-14","tags":[]},{"id":"poem-4d7fc1bb2c9e8728371585f1","title":"饯王晙巡边","author":"明皇帝","dynasty":"唐","verses":["振武威荒服，扬文肃远墟。","金坛申将礼，玉节授军符。","免胄三方外，衔刀万里余。","昔时吴会静，今日虏庭虚。","分阃仍推毂，援桴且训车。","风扬旌斾远，雨洗甲兵初。","坐见台阶谧，行闻祅祲除。","檄来虽插羽，箭去亦飞书。","舟檝功须著，盐梅望匪疎。","不应陈七德，欲使化先敷。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-99dbd2f9-5430-4250-8073-6925811afb72","tags":[]},{"id":"poem-4d808ddd76f36aa58bd0e466","title":"李潮八分小篆歌","author":"杜甫","dynasty":"唐","verses":["苍颉鸟迹既茫昧，字体变化如浮云。","陈仓石鼓又已讹，大小二篆生八分。","秦有李斯汉蔡邕，中间作者寂不闻。","峄山之碑野火焚，枣木传客肥失真。","苦县光和尚骨立，书贵瘦硬方通神。","惜哉李蔡不复得，吾甥李潮下笔亲。","尚书韩择木，骑曹蔡有邻。","开元已来数八分，潮也奄有二子成三人。","况潮小篆逼秦相，快劒长戟森相向。","八分一字直百金，蛟龙盘拏肉屈强。","吴郡张颠夸草书，草书非古空雄壮。","岂如吾甥不流宕，丞相中郎丈人行。","巴东逢李潮，逾月求我歌。","我今衰老才力薄，潮乎潮乎奈汝何。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-0a14f11c-1fa5-4d47-abf7-7fd511b82373","tags":[]},{"id":"poem-4d8a14c8d10f7bd7849bf274","title":"诗一首","author":"张𬸦","dynasty":"唐","verses":["得意似鸳鸯，情乖若吴越。","不向君边尽，更知何处歇。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-5ad82c7c-4b3e-4517-85cf-28972a821dcf","tags":[]},{"id":"poem-4d8dc17353aca580999fdf68","title":"斜谷道","author":"于邺","dynasty":"唐","verses":["乱峰连叠嶂，千里绿峨峨。","蜀国路如此，游人车亦过。","远烟当驿歛，骤雨逐风多。","独忆紫芝叟，临风歌旧歌。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-68b97b04-7b2d-4e1f-a271-f0b0ac137f13","tags":[]},{"id":"poem-4d93cb543009723c43e5fc1f","title":"秋晚","author":"李咸用","dynasty":"唐","verses":["斜阳山雨外，秋色思无穷。","柳叶飘干翠，枫枝撼碎红。","鬓毛看似雪，生计尚如蓬。","不及樵童乐，蒹葭一笛风。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-5f0518c3-c371-48cb-aee5-480af9a863ad","tags":[]},{"id":"poem-4d93e8c9b1d744189a83720a","title":"周世宗时被召作（题拟）","author":"陈抟","dynasty":"唐","verses":["草泽吾皇诏，图南抟姓陈。","三峰十年客。","四海一闲人。","世态从来薄，诗情自得真。","超然居物外，何必使为臣。","（见陶岳《五代史补》卷五。","）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-fd1ba265-3ab7-4348-b997-fa2ec04243b5","tags":[]},{"id":"poem-4d98e28b60efa4afd015bb23","title":"闻逝者自惊","author":"李嘉祐","dynasty":"唐","verses":["亦知死是人间事，年老闻之心自疑。","黄卷清琴总为累，落花流水共添悲。","愿将从药看真诀，又欲休官就本师。","儿女眼前难喜舍，弥怜双鬓渐如丝。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-25e0e52b-b822-44f8-9cc5-4ffa1a63948e","tags":[]},{"id":"poem-4d9cb8e70c4f385bd4e75fb7","title":"小引","author":"刘唐卿《白兔记》","dynasty":"元","verses":["(净上)庙官来，庙官来，打点香炉蜡烛台。","但办志诚心，何劳神不灵？但办志诚意，何劳神不至？。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-8810","tags":[]},{"id":"poem-4d9d1016ebdcf6f89cf44a21","title":"九怀·株昭","author":"王褒","dynasty":"汉","verses":["悲哉于嗟兮，心内切磋。","款冬而生兮，凋彼叶柯。","瓦砾进宝兮，捐弃随和。","铅刀厉御兮，顿弃太阿。","骥垂两耳兮，中坂蹉跎。","蹇驴服驾兮，无用日多。","修洁处幽兮，贵宠沙劘。","凤皇不翔兮，鹑𫛩飞扬。","乘虹骖蜺兮，载云变化。","焦明开路兮，后属青蛇。","步骤桂林兮，超骧卷阿。","丘陵翔儛兮，谿谷悲歌。","神章灵篇兮，赴曲相和。","余私娱兹兮，孰哉复加。","还顾世俗兮，坏败罔罗。","卷佩将逝兮，涕流滂沲。","乱曰：皇门开兮照下土，株秽除兮兰芷睹。","四佞放兮后得禹，圣舜摄兮昭尧绪，孰能若兮原为辅。"],"enabled":true,"collection":"楚辞","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/楚辞/chuci.json#record-46","tags":[]},{"id":"poem-4da83fe04216fae29ac27049","title":"送杨氏女","author":"韦应物","dynasty":"唐","verses":["永日方戚戚，出门复悠悠。","女子今有行，大江溯轻舟。","尔辈况无恃，抚念益慈柔。","幼为长所育，两别泣不休。","对此结中肠，义往难复留。","自小阙内训，事姑贻我忧。","赖兹托令门，仁恤庶无尤。","贫俭诚所尚，资从岂待周。","孝恭遵妇道，容止顺其猷。","别离在今晨，见尔当何秋。","居闲始自遣，临感忽难收。","归来视幼女，零泪缘缨流。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-f800050a-d7a0-4f12-a614-17fe23df8f41","tags":["唐诗三百首","送别","感伤","五言古诗"]},{"id":"poem-4dad9f8fbc0b85353a65b7a0","title":"满庭芳","author":"萧德祥《小孙屠》","dynasty":"元","verses":["昔日孙家，双名必达。","花朝行乐春风。","琼梅李氏，卖酒亭上幸相逢。","从此娉为夫妇。","兄弟谋苦不相从。","因往外，琼梅水性，再续旧情浓。","暗去梅香首级，潜奔它处，夫主劳笼。","陷兄弟必贵，盆吊死郊中。","幸得天教再活，逢嫂妇说破狂踪。","三见鬼，一齐擒住，迢断在开封。","(末下)。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-8562","tags":[]},{"id":"poem-4daf8b56c3156f3d37692b15","title":"老病相攻偶成长句寄秘阁侍郎","author":"李昉","dynasty":"宋","verses":["衰病增加我斗谙，头风目眩一般般。","纵逢杯酒都无味，任听笙歌亦寡欢。","朝退便思亲枕簟，客来多倦著衣冠。","行行渐近悬车岁，转恐君恩报答难。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.0.json#record-55e68b8e-4966-4109-a468-93d5a8d779b3","tags":[]},{"id":"poem-4db087367b253b598ba05128","title":"河南府试十二月乐词 闰月","author":"李贺","dynasty":"唐","verses":["帝重光，年重时。","七十二候回环推，天官玉琯灰剩飞。","今岁何长来岁迟，王母移桃献天子。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-851219e8-5993-4d52-868a-8dfe431c0ddb","tags":[]},{"id":"poem-4db592f948396c2b1efeaea4","title":"游华山云际寺","author":"张乔","dynasty":"唐","verses":["少华中峰寺，高秋众景归。","地连秦塞起，河隔晋山微。","晚木蝉相应，凉天鴈并飞。","殷勤记岩石，秪恐再来稀。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-11bab6c9-81b8-4c27-a60c-9b50385cdf35","tags":[]},{"id":"poem-4dc1926a442bad5458a7fc06","title":"送古之奇赴安西幕","author":"李端","dynasty":"唐","verses":["畴昔十年兄，相逢五校营。","今宵举杯酒，陇月见军城。","堠火经阴绝，边人接晓行。","殷勤送书记，强虏几时平。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-e9013cb0-39cc-4b2a-9f1d-6b466b6a2389","tags":[]},{"id":"poem-4dc4d521638496cfd5df0351","title":"永明山居诗（六十九首） 四十五","author":"延寿","dynasty":"唐","verses":["擕筇闲步望山行，竟日逍遥任野情。","上岭梯登危石侧，渡溪桥踏古槎横。","绿罗水皱岩根急，红锦霞舒海面明。","一轴咏怀高尚意，援毫因事偶吟成。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-33adf737-745a-448c-84ec-d560250464cc","tags":[]},{"id":"poem-4dd0b8f23e18aaf49e6185c1","title":"浣沙溪·春水轻波浸绿苔","author":"毛文锡","dynasty":"五代","verses":["春水轻波浸绿苔，楷杷洲上紫檀开。","晴天眠沙㶉𫛶稳，暖相偎。","罗袜生尘游女过，有人逢着弄珠回。","兰麝飘香初解佩，忘归来。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-5-juan.json#record-23","tags":[]},{"id":"poem-4dd214024486bd03d4b4db27","title":"短歌行送祁录事归合州因寄苏使君","author":"杜甫","dynasty":"唐","verses":["前者途中一相见，人事经年记君面。","后生相动何寂寥，君有长才不贫贱。","君今起柁春江流，余亦沙边具小舟。","幸为达书贤府主，江花未尽会江楼。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-f1ada7f0-b14f-4660-8811-aaf1b4a6b67b","tags":[]},{"id":"poem-4dd5b8fbd4b2f5da408ba4f5","title":"劝人 十七","author":"义存","dynasty":"唐","verses":["磨砖不成镜，虚空终有月。","火急自提取，莫受多生屑。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-7f65b1e2-ef89-459d-a250-e7956139011f","tags":[]},{"id":"poem-4dd7f070e890466f3098c898","title":"海阳泉","author":"无名氏","dynasty":"唐","verses":["人谁无耽爱，各亦有所偏。","于吾喜尚中，不厌千万泉。","诚知湟水曲，远在南海壖。","自从得海阳，便欲终老焉。","怪石状五岳，旋回枕深渊。","激繁似涌云，静同冰镜悬。","吾欲以海阳，跨于河洛间。","使彼云林客，来游皆忘还。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-add85a26-6caf-4763-97e7-6a02560b90f9","tags":[]},{"id":"poem-4de39789ccfe0b7759418b43","title":"题山中别业","author":"李端","dynasty":"唐","verses":["旧宅在山中，闲门与寺通。","往来黄叶路，交结白头翁。","晚笋难成竹，秋花不满丛。","生涯祗麤粝，吾岂讳言穷。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-95d54531-dd2a-4f05-8064-c28224919dfc","tags":[]},{"id":"poem-4dedaca77f5f1f16e9c1e14f","title":"赠越客","author":"赵嘏","dynasty":"唐","verses":["故国波涛隔，明时心久留。","献书双阙晚，看月五陵秋。","南棹何当返，长江忆共游。","定知钓鱼伴，相望在汀州。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-50e5ef86-c74f-46ff-9adf-c27b7b2e4c8c","tags":["长江"]},{"id":"poem-4dee72776869b60204b57058","title":"忆昔一首","author":"赵崇嶓","dynasty":"宋","verses":["忆昔城南会，珮马轻春风。","芳华感人心，折赠以为容。","俯仰一相失，去若南飞鸿。","青青女萝衣，蔚蔚石上松。","岁寒无夕秀，安得长相从。","愿为日月光，落君怀袖中。","三五如循环，千里宛可同。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.210000.json#record-b86e25b6-07df-4ca8-8acf-d6448b918176","tags":[]},{"id":"poem-4df5f5f6db4ecf3d80758486","title":"和王季文题九华山","author":"神颖","dynasty":"唐","verses":["众岳雄分野，九华镇南朝。","彩笔凝空远，崔嵬寄青霄。","龙潭古仙府，灵药今不凋。","莹为沧海镜，烟霞作荒标。","造化心数奇，性状精气饶。","玉树郁玲珑，天籁韵萧寥。","寂寂寻乳窦，兢兢行石桥。","通泉漱云母，藉草萦香苕。","我住幽且深，君赏昏复朝。","稀逢发清唱，片片霜凌飙。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-a6ceb4b9-5559-43fa-8c86-f3e5dffcc54f","tags":["九华山"]},{"id":"poem-4dfdfe2e0ea60dc82ab18169","title":"南安岩恭谒定光圆应禅师二首  其一","author":"李纲","dynasty":"宋","verses":["白衣隐去碧岩空，塔庙岿然海峤东。","分化何殊遽如许，赠诗多写以之中。","青山绿水年年好，明月清风处处同。","好住一方为庇荫，不须追逐泗滨翁。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.90000.json#record-72a8d053-f184-447e-bb3c-e6c92ff2ea9f","tags":[]},{"id":"poem-4e04e8037244b663fe7e3bca","title":"用诸公本韵各和一篇共三首  其三","author":"苏颂","dynasty":"宋","verses":["继踵螭阶入右垣，曾参何敢望渊骞。","复门重庆登庸命，枢合仍陪话旧筵。","贵贱交情都不改，始终风节固难迁。","公卿平日推高誉，朝论今谁过邓先。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.30000.json#record-530c9dc6-aa8a-44d3-938d-c4a0dd7815d5","tags":[]},{"id":"poem-4e0a1d814113864af4305f02","title":"杏花天·绿丝低拂鸳鸯浦","author":"姜夔","dynasty":"宋","verses":["绿丝低拂鸳鸯浦。","想桃叶、当时唤渡。","又将愁眼与春风，待去。","倚兰桡、更少驻。","金陵路。","莺吟燕舞。","算潮水、知人最苦。","满汀芳草不成归，日暮。","更移舟、向甚处。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-123","tags":["宋词三百首"]},{"id":"poem-4e0b19df3b2a43d661a928f1","title":"古兴","author":"李嘉祐","dynasty":"唐","verses":["十五小家女，双鬟人不如。","蛾眉暂一见，可直千金余。","自从得向蓬莱里，出入金舆乘玉趾。","梧桐树上春鸦鸣，晓伴君王犹未起。","莫道君恩长不休，婕妤团扇苦悲秋。","君看魏帝邺都里，惟有铜台漳水流。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-6474e381-8e86-4d81-859b-c164f2155a19","tags":[]},{"id":"poem-4e13322130819767caffdd6a","title":"七月一日晓入太行山","author":"李贺","dynasty":"唐","verses":["一夕遶山秋，香露溘蒙菉。","新桥倚云阪，候虫嘶露朴。","洛南今已远，越衾谁为熟。","石气何凄凄，老莎如短镞。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-7cde13a8-f1cf-4ac8-b723-5faaf5b0029d","tags":[]},{"id":"poem-4e15fd851513e78749c9d52a","title":"送友人之江南","author":"项斯","dynasty":"唐","verses":["东南路苦辛，去路见无因。","万里此相送，故交谁更亲。","日浮汀草绿，烟霁海山春。","握手无别赠，为予书札频。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-3e6cbfa8-7b51-4e99-b66a-1a4c22ad1905","tags":[]},{"id":"poem-4e23c0941698006adec624db","title":"将之苕溪戏作呈诸友  其一","author":"米芾","dynasty":"宋","verses":["松竹留因夏，溪山去为秋。","久赓白雪咏，更度采菱讴。","缕玉鲈堆案，团金橘满洲。","水宫无限景，载与谢公游。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.60000.json#record-cfd6ac95-5c23-45d0-9f4a-790a037d1521","tags":[]},{"id":"poem-4e2467d15b997e36b23fee60","title":"浣溪沙·过隙光阴还自催","author":"张纲","dynasty":"宋","verses":["过隙光阴还自催。","生朝又送一年来。","宴堂深处强追陪。","眼眩岂堪花里笑，眉攒聊向酒边开。","与君同醉莫辞杯。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.6000.json#record-653","tags":[]},{"id":"poem-4e2aa146b35c8029e252ed3f","title":"送张炼师还峨嵋山","author":"司空曙","dynasty":"唐","verses":["太一天坛天柱西，垂萝为幌石为梯。","前登灵境青霄绝，下视人间白日低。","松籁万声和管磐，丹光五色杂虹蜺。","春山一入寻无路，鸟响烟深水满溪。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-d41d9356-525f-4680-93cc-724d67035925","tags":["峨眉山"]},{"id":"poem-4e2ea19f3f01e17bd4a9d077","title":"次韵王省干  其一","author":"陈造","dynasty":"宋","verses":["南橘合嘉颂，为枳缘逾淮。","黄浊转眼涸，一昨弥两涯。","志士抱根柢，千古容兴怀。","后生事虫篆，蚁穴鏖檀槐。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.150000.json#record-f113ec66-1572-47e5-bda2-1d666f6c2ec2","tags":[]},{"id":"poem-4e3a9f609bb3a6c2a817154e","title":"前腔","author":"徐田臣《杀狗记》","dynasty":"元","verses":["(贴)告官人听咨启，岂不晓其中意？我娘行贤达聪明，提说故事比喻。","曹丕妒忌休学取，愿学昭王怜兄弟。","望员外息怒停嗔，从是改非。","赛过关张，到底都是乔的。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-1812","tags":[]},{"id":"poem-4e456f7490b33290aa1df96f","title":"秋日忆暕上人","author":"李端","dynasty":"唐","verses":["一从持钵别，更未到人间。","好静居贫寺，遗名弃近山。","雨前缝百衲，叶下闭重关。","若便浔阳去，须将旧客还。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-624cc745-9bec-4afc-9032-52042f103c9e","tags":[]},{"id":"poem-4e4626162fca9dca5bb00559","title":"前腔","author":"柯丹邱《荆钗记》","dynasty":"元","verses":["［净］迤逦松篁迳里，见野塘溶溶水没沙嘴。","鸥凫往来，出没又还惊飞。","危桥跨涧人过稀，只见漠漠平沙接远堤。","［合］途中趣，真是奇，绿杨枝上啭黄鹂。","难禁受，闻子规，声声叫道不如归。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-8143","tags":[]},{"id":"poem-4e477ab232b3184b1b2d6723","title":"长寿仙促拍·舜德日辉光","author":"曹勋","dynasty":"宋","verses":["舜德日辉光，正初冬盛期。","东朝喜、诞生时。","向彤闱、清净均化有，自然和气。","长生久视，金殿熙熙。","宴瑶池。","袆衣俱侍、玳筵启。","花如锦、耀朝晖。","太平际天子，天下养、共瞻诚意。","南山虔祝，亿万同岁。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.6000.json#record-150","tags":[]},{"id":"poem-4e4c55546bfa7e735dcb7e53","title":"奉荅燕公","author":"赵冬曦","dynasty":"唐","verses":["语别意凄凄，零陵湘水西。","佳人金谷返，爱子洞庭迷。","旧馆逢花发，他山值鸟啼。","江天千里望，谁见绿苹齐。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-82badfaa-a20f-4946-9171-f89b314d8316","tags":["洞庭湖"]},{"id":"poem-4e50788b3cea2147e7af7ddb","title":"汉武帝于宫中宴西王母","author":"曹唐","dynasty":"唐","verses":["鼇岫云低太一坛，武皇斋洁不胜懽。","长生碧字期亲署，延寿丹泉许细看。","劒佩有声宫树静，星河无影禁花寒。","秋风褭褭月朗朗，玉女清歌一夜阑。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-d21e0ad6-2739-41bc-8476-7af65282a844","tags":[]},{"id":"poem-4e5a928b1ba5539a982c8298","title":"凉夜","author":"王镃","dynasty":"宋","verses":["断阶露草湿鸣蛩，桐树凉生落叶中。","月上小楼人未睡，曲栏敲遍倚西风。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.240000.json#record-781cfd83-8282-4e4a-a820-9646ddcd0d51","tags":[]},{"id":"poem-4e5c6c5c218278221b8a74eb","title":"洛阳桥","author":"王十朋","dynasty":"宋","verses":["北望中原万里遥，南来喜见洛阳桥。","人行跨海金鼇背，亭压横空玉虹腰。","功不自成因砥柱，患宜预备有风潮。","蔡公力量真刚者，遗爱胜于郑国侨。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.120000.json#record-b767e243-1099-417e-a611-15e8f459679a","tags":[]},{"id":"poem-4e5c8d9269c6b422318998f9","title":"咏怀古迹五首 二","author":"杜甫","dynasty":"唐","verses":["摇落深知宋玉悲，风流儒雅亦吾师。","怅望千秋一洒泪，萧条异代不同时。","江山故宅空文藻，云雨荒台岂梦思。","最是楚宫俱泯灭，舟人指点到今疑。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-acbe1729-cefd-4678-9719-09c5c9c27db0","tags":["唐诗三百首","隋・唐・五代","七言律诗","怀古","抒怀"]},{"id":"poem-4e73b32278936e41c2e6d6db","title":"续东野铜斗歌送平江张都承  其二","author":"释居简","dynasty":"宋","verses":["老我名铜斗，可糁亦可糜。","旦旦数瓶粟，不饱亭午饥。","层冰十万钱，剖蚌黳鬓丝。","宏功厚斯享，毋使宏功隳。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.180000.json#record-8782e4e8-d63c-49a8-9c79-500eba688343","tags":[]},{"id":"poem-4e7e3b61fb41bb3ddc20aa7b","title":"谒金门","author":"高明《蔡伯喈琵琶记》","dynasty":"元","verses":["春梦断，临镜绿云撩乱。","闻道才郎游上苑，又添离别叹。","(生接唱)苦被爹行逼遣，脉咏此情何限。","骨肉一朝成拆散，可怜难舍拚。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-4942","tags":[]},{"id":"poem-4e8b2a1375fd750a00464464","title":"柘臯短吟","author":"陈造","dynasty":"宋","verses":["铁山横飞截平野，宁复江流饮胡马。","大酋胆落狐鼠逃，虎头将军自天下。","拂庐连络屯长云，提戈敢谓秦无人。","惊霆白昼振解叶，淮地一扫留无尘。","歌谣千载淮民口，将军归饮策勋酒。","乌袍使者来如烟，腾书乞和胡稽首。","蝇鸣鸱噪初不闻，贾怒一举雌雄分。","辛勤结发七十战，数奇堪笑李将军。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.150000.json#record-a805687c-b777-4bc3-a9e3-f3898134b407","tags":[]},{"id":"poem-4e8c50d4de3be7be8a4a7f27","title":"生查子·暖日策花骢","author":"孙光宪","dynasty":"五代","verses":["暖日策花骢，亸鞚垂杨陌。","芳草惹烟青，落絮随风白。","谁家绣毂动香尘，隐遇难神仙客。","狂杀玉鞭郎，咫尺音容隔。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-8-juan.json#record-12","tags":[]},{"id":"poem-4e8fa0bb26f28fc118e9e6cd","title":"侍宴桃花园咏桃花应制","author":"赵彦昭","dynasty":"唐","verses":["红萼竞燃春苑曙，粉茸新吐御筵开。","长年愿奉西王母，近侍惭无东朔才。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-d4b40cb2-2a03-47a8-98e8-ce7eec3a275d","tags":[]},{"id":"poem-4e918e6a061f3169f61d62b1","title":"送郑尚书赴广州","author":"张籍","dynasty":"唐","verses":["圣朝选将持符节，内使宣时百辟听。","海北蛮夷来舞蹈，岭南封管送图经。","白鹇飞遶迎官舫，红槿开当䜩客亭。","此处莫言多瘴疠，天边看取老人星。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-43966955-c47e-428d-92e8-0803ac8bb4de","tags":[]},{"id":"poem-4e95858cdf4263f65763d57a","title":"三代门 太公","author":"周昙","dynasty":"唐","verses":["昌猎关西纣猎东，纣怜崇虎弃非熊。","危邦自谓多麟凤，肯把王纲取钓翁。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-3c5fdfab-f430-4d11-ac34-7a1e0304f0d7","tags":[]},{"id":"poem-4e99ac1fb332c8c697632121","title":"鸡鸣","author":"佚名","dynasty":"先秦","verses":["鸡既鸣矣，朝既盈矣。匪鸡则鸣，苍蝇之声。","东方明矣，朝既昌矣。匪东方则明，月出之光。","虫飞薨薨，甘与子同梦。会且归矣，无庶予子憎。"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-95","tags":[]},{"id":"poem-4e9a53bb7163b457976a78fb","title":"寻阳村舍","author":"张乔","dynasty":"唐","verses":["荒林寄远居，坐卧见樵渔。","夜火随船远，寒更出郡疎。","雪迷登岳路，风阻转江书。","寂寞高窗下，思乡岁欲除。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-17ffe0e8-195d-4f2a-b378-40658be1beac","tags":[]},{"id":"poem-4ea006578795cd04934db912","title":"醉桃源・阮郎归·固穷斋里语吾生","author":"韩淲","dynasty":"宋","verses":["固穷斋里语吾生。","言之必可行。","扶疏夏木既啼莺。","更逢鱼计成。","多雅尚，少时情。","沧浪渔父缨。","高歌宁与俗争鸣。","朱弦疏越声。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.2000.json#record-436","tags":[]},{"id":"poem-4ea265fcee1469a9690fa74d","title":"谢新恩·冉冉秋光留不住","author":"李煜","dynasty":"五代","verses":["冉冉秋光留不住，满阶红叶暮。","又是过重阳，台榭登临处。","茱萸香坠，紫菊气，飘庭户，晚烟笼细雨。","嗈嗈新雁咽寒声，愁恨年年长相侣。"],"enabled":true,"collection":"南唐二主词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/nantang/poetrys.json#record-34","tags":[]},{"id":"poem-4ea91bb943906d158050f87f","title":"和殷衙推春霖即事","author":"李咸用","dynasty":"唐","verses":["东风吹暖雨，润下不能休。","古道云横白，移时客共愁。","绿沈莎似藻，红泛叶为舟。","忽起江湖兴，疑邻畎浍流。","此时无胜会，何处滞奇游？","阵急如酣战，点麤成乱沤。","竹因添洒落，松得长飕飗。","花惨闲庭晚，兰深曲径幽。","丝牵汀鸟足，线挂岳猿头。","天地昏同醉，寰区浩欲浮。","柳眉低带泣，蒲剑锐初抽。","石燕飜空重，虫罗缀滴稠。","荷倾蛟泪尽，岩拆电鞭收。","岂直望尧喜，却怀微禹忧。","树滋堪采菌，矶没懒垂钩。","腥觉闻龙气，寒宜拥豹裘。","名膏那作沴，思稔必通侯。","蚌鹬徒喧竞，笙歌罢献酬。","山川藏秀媚，草木逞调柔。","极目非吾意，行吟独下楼。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-d1160324-9771-4072-aba9-2d1c31cb3e76","tags":[]},{"id":"poem-4eac38a47142598a5908406d","title":"自淇涉黄河途中作十三首 七","author":"高适","dynasty":"唐","verses":["乱流自兹远，倚檝时一望。","遥见楚汉城，崔嵬高山上。","天道昔未测，人心无所向。","屠钓称侯王，龙蛇争霸王。","缅怀多杀戮，顾此生惨怆。","圣代休甲兵，吾其得闲放。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-b0e51eac-3f11-473d-b3de-f2e9bdc1e74f","tags":["黄河"]},{"id":"poem-4ead55016540528f08d9d1fb","title":"宴清都·春讯飞琼管","author":"卢祖皋","dynasty":"宋","verses":["春讯飞琼管。","风日薄、度墙啼鸟声乱。","江城次第，笙歌翠合，绮罗香暖。","溶溶涧渌冰泮。","醉梦里、年华暗换。","料黛眉重锁隋堤，芳心还动梁苑。","新来雁阔云音，鸾分槛影，无计重见。","啼春细雨，笼愁澹月，恁时庭院。","离肠未语先断。","算犹有、凭高望眼。","更那堪、芳草连天，飞梅弄晚。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-187","tags":["宋词三百首"]},{"id":"poem-4eb549feb05dbd41d24609c7","title":"杜鹃花","author":"释居简","dynasty":"宋","verses":["染得深红剪万葩，春归独自绚韶华。","丁宁莫受西风误，误使人看顷刻花。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.180000.json#record-2ff939e4-c1e1-4301-9db6-fab4c68cbc1c","tags":[]},{"id":"poem-4eba871c03b9722d34dd54b2","title":"相和歌辞 燕歌行","author":"高适","dynasty":"唐","verses":["汉家烟尘在东北，汉将辞家破残贼。","男儿本自重横行，天子非常赐颜色。","𪭢金伐鼓下榆关，旌旗逶迤碣石间。","校尉羽书飞瀚海，单于猎火照狼山。","山川萧条极边土，胡骑凭凌杂风雨。","战士军前半死生，美人帐下犹歌舞。","大漠穷秋塞草衰，孤城落日鬬兵稀。","身当恩遇常轻敌，力尽关山未解围。","铁衣远戍辛勤久，玉箸应啼别离后。","少妇城南欲断肠，征人蓟北空回首。","边风飘飘那可度，绝域苍茫更何有。","杀气三日作阵云，寒声一夜传刁斗。","相看白刃血纷纷，死节从来岂顾勋。","君不见沙场征战苦，至今犹忆李将军。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-09788f19-1e11-4394-a543-0edf2cfdcae9","tags":["唐诗三百首"]},{"id":"poem-4eced3fae0a4165b051bdccb","title":"菩萨蛮·铜簧韵脆锵寒竹","author":"李煜","dynasty":"五代","verses":["铜簧韵脆锵寒竹，新声慢奏移纤玉。","眼色暗相钩，秋波横欲流。","雨云深绣户，未便谐衷素。","宴罢又成空，魂迷春梦中。"],"enabled":true,"collection":"南唐二主词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/nantang/poetrys.json#record-23","tags":[]},{"id":"poem-4ed52be2a2d6e902de639def","title":"满江红·春欲来时","author":"程过","dynasty":"宋","verses":["春欲来时，长是与、江梅花约。","又还向、竹林疏处，一枝开却。","对酒渐惊身老大，看花应念人离索。","但十分、沈醉祝东君，长如昨。","芳草渡，孤舟泊。","山敛黛，天垂幕。","黯销魂、无奈暮云残角。","便好折来和雪戴，莫教酒醒随风落。","待殷勤、留此记相思，谁堪托。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.6000.json#record-632","tags":[]},{"id":"poem-4ed950aa9ce15cfa25148438","title":"题禅堂壁间","author":"米芾","dynasty":"宋","verses":["水石相搏，风竹相吞。","炉烟方袅，草木自欣。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.60000.json#record-455b6d0e-a85f-4082-8517-0b039f72c293","tags":[]},{"id":"poem-4ed9b4ac4f5063ca034ecb1d","title":"夜雨寄北","author":"李商隐","dynasty":"唐","verses":["君问归期未有期，巴山夜雨涨秋池。","何当共剪西窗烛，却话巴山夜雨时。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-75db753d-e7da-48a1-a6c0-6ed9147e58db","tags":["唐诗三百首","思念","写雨","写景","景中情","初中古诗","高中古诗","七言绝句","爱情","三年级上册","雨","七年级上册(课外)"]},{"id":"poem-4edc1df9016b8723df14a4f8","title":"寄全椒山中道士","author":"韦应物","dynasty":"唐","verses":["今朝郡斋冷，忽念山中客。","涧底束荆薪，归来煮白石。","欲持一瓢酒，远慰风雨夕。","落叶满空山，何处寻行迹。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-46503396-3bb3-449c-9c84-f2ff232f7949","tags":["唐诗三百首","五言古诗","怀念"]},{"id":"poem-4ede32143d4157c22a01a6a3","title":"八哀诗 故秘书少监武功苏公源明","author":"杜甫","dynasty":"唐","verses":["武功少也孤，徒步客徐衮。","读书东岳中，十载考坟典。","时下莱芜郭，忍饥浮云𪩘。","负米晚为身，每食脸必泫。","夜字照𦶟薪，垢衣生碧藓。","庶以勤苦志，报兹劬劳显。","学蔚醇儒姿，文包旧史善。","洒落辞幽人，归来潜京辇。","射君东堂策，宗匠集精选。","制可题未干，乙科已大阐。","文章日自负，吏禄亦累践。","晨趋阊阖内，足蹋宿昔趼。","一麾出守还，黄屋朔风卷。","不暇陪八骏，虏庭悲所遣。","平生满尊酒，断此朋知展。","忧愤病二秋，有恨石可转。","肃宗复社稷，得无逆顺辨。","范晔顾其儿，李斯忆黄犬。","秘书茂松意，溟涨本末浅。","青荧芙蓉劒，犀兕岂独剸。","反为后辈亵，予实苦怀缅。","煌煌斋房芝，事绝万手搴。","垂之俟来者，正始征劝勉。","不要悬黄金，胡为投乳贙。","结交三十载，吾与谁游衍。","荥阳复冥莫，罪罟已横罥。","呜呼子逝日，始泰则终蹇。","长安米万钱，凋丧尽余喘。","战伐何当解，归帆阻清沔。","尚缠漳水疾，永负蒿里饯。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-0d07875d-bf3e-4a2e-9139-ba767079c8ad","tags":[]},{"id":"poem-4ee2c7c0029e051e905493cc","title":"云门山投龙诗刻（并序）","author":"赵居贞","dynasty":"唐","verses":["（按《全唐诗》卷二百五十八收此诗，《山左金石志》石刻亦载之，惟异文较多，且序中有二十余字，诗中有四句为《全唐诗》所无，故重为录出，而以《全唐诗》校之。","）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-a1869336-c181-482e-922b-093660e76dcc","tags":[]},{"id":"poem-4ee992d1ff42f4860c04a887","title":"锁窗寒・琐寒窗·暗柳啼鸦","author":"周邦彦","dynasty":"宋","verses":["暗柳啼鸦，单衣伫立，小帘朱户。","桐花半亩，静锁一庭愁雨。","洒空阶，夜阑未休，故人剪烛西窗语。","似楚江暝宿，风灯零乱，少年羁旅。","迟暮。","嬉游处。","正店舍无烟，禁城百五。","旗亭唤酒，付与高阳俦侣。","想东园，桃李自春，小唇秀靥今在否。","到归时，定有残英，待客携尊俎。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-224","tags":["宋词三百首"]},{"id":"poem-4eea34a77fa97315c65a9ce5","title":"祝英台序","author":"高明《蔡伯喈琵琶记》","dynasty":"元","verses":["把几分春三月景，分付与东流。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-4925","tags":[]},{"id":"poem-4eecbfb15006ad527033ffa7","title":"自淇涉黄河途中作十三首 二","author":"高适","dynasty":"唐","verses":["清晨泛中流，羽族满汀渚。","黄鹄何处来，昂藏寡俦侣。","飞鸣无人见，饮啄岂得所。","云汉尔固知，胡为不轻举。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-6ec03821-1ece-4cdc-97cb-c7b976ac47b1","tags":["黄河"]},{"id":"poem-4ef56d6b3c0c4695a000a35c","title":"江上逢司空曙","author":"李端","dynasty":"唐","verses":["共尔髫年故，相逢万里余。","新春两行泪，故国一封书。","夏口帆初落，涔阳雁正疎。","唯当执杯酒，暂食汉江鱼。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-5e2d8a26-816a-42a0-a793-43cb68b807be","tags":[]},{"id":"poem-4ef671c603501f3f7fc72740","title":"剔银灯","author":"刘唐卿《白兔记》","dynasty":"元","verses":["当答谢瓜园中土地，劳看守刀甲头盔兵书宝剑埋藏此，得前程方来取你。","神明听吾诉与，休泄漏天公事机。","远远望见一个妇人，好似三姐。","不免躲在一边则个。","要知心腹事，但听口中言。","(躲介)。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-8873","tags":[]},{"id":"poem-4ef97de0347ed5012589f55c","title":"将离江上作","author":"张乔","dynasty":"唐","verses":["白衣归树下，青草恋江边。","三楚足深隐，五陵多少年。","寂寥闻蜀魄，清绝怨湘弦。","岐路在何处，西行心渺然。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-0c281e09-5785-4391-af95-21b76e2c35dc","tags":[]},{"id":"poem-4efb0ede64d787d1c3d00017","title":"咏史诗 河梁","author":"胡曾","dynasty":"唐","verses":["汉家英杰出皇都，携手河梁话入胡。","不是子卿全大节，也应低首拜单于。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-5bf02c5c-abc0-41d0-a0f2-a8105a351b6e","tags":[]},{"id":"poem-4efe47e9813d53de9eb0e3bf","title":"插花吟","author":"邵雍","dynasty":"宋","verses":["头上花枝照酒卮，酒卮中有好花枝。","身经两世太平日，眼见四朝全盛时。","况复筋骸粗康健，那堪时节正芳菲。","酒涵花影红光溜，争忍花前不醉归。"],"enabled":true,"collection":"千家诗","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/蒙学/qianjiashi.json#record-插花吟","tags":[]},{"id":"poem-4f12171840507ca817a59cae","title":"多丽·想人生","author":"聂冠卿","dynasty":"宋","verses":["想人生，美景良辰堪惜。","问其间、赏心乐事，就中难是并得。","况东城、凤台沙苑，泛晴波、浅照金碧。","露洗华桐，烟霏丝柳，绿阴摇曳，荡春一色。","画堂迥、玉簪琼佩，高会尽词客。","清欢久、重然绛蜡，别就瑶席。","有翩若轻鸿体态，暮为行雨标格。","逞朱唇、缓歌妖丽，似听流莺乱花隔。","慢舞萦回，娇鬟低亸，腰肢纤细困无力。","忍分散、彩云归后，何处更寻觅。","休辞醉，明月好花，莫谩轻掷。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.0.json#record-38","tags":[]},{"id":"poem-4f16a9192f8e282845fe9152","title":"与弟姪饮梅花下分韵得香字","author":"张栻","dynasty":"宋","verses":["日多色愈正，春和天与香。","提携一樽酒，问讯满园芳。","嗣岁诗多思，怀人心甚长。","更须多秉烛，玉立胜红粧。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.150000.json#record-4014c09c-f103-481b-bdb5-8884a88d6a33","tags":[]},{"id":"poem-4f16f5ebef49504285c8228f","title":"咏史诗 东海","author":"胡曾","dynasty":"唐","verses":["东巡玉辇委泉台，徐福楼船尚未回。","自是祖龙先下世，不关无路到蓬莱。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-ae5d792a-bc45-4a29-9948-757e6c5da88b","tags":[]},{"id":"poem-4f1ad8fb75a0b0512c0e6cac","title":"杭州秋日别故友","author":"长孙佐辅","dynasty":"唐","verses":["相见又相别，大江秋水深。","悲欢一世事，去住两乡心。","淅沥篱下叶，凄清阶上琴。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-3355f85a-00ae-422d-b446-f3df558da00c","tags":[]},{"id":"poem-4f20b61e65ae732da975b0e7","title":"送吉校书东归","author":"司空曙","dynasty":"唐","verses":["少年芸阁吏，罢直暂归休。","独与亲知别，行逢江海秋。","听猨看楚岫，随雁到吴洲。","处处园林好，何人待子猷。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-7e77befb-75da-4226-b95d-0b44902bbb2e","tags":[]},{"id":"poem-4f21919646ddf45e7bd1a7eb","title":"颂古七十六首  其九","author":"释士珪","dynasty":"宋","verses":["海水翻空衮底流，鱼龙虾蟹信沉浮。","可怜金色头陀子，直至如今笑未休。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.90000.json#record-3f3a7e4b-b1b7-4699-b9e3-303a8a820eba","tags":[]},{"id":"poem-4f28f4425da8f35c44f55243","title":"日诗","author":"赵匡胤","dynasty":"唐","verses":["欲出未出光辣达（一作「太阳初出光赫赫」），千山万山如火发，须臾走向天下来（一作「一轮顷刻上天衢」），逐却（一作「退」）残（一作「群」）星赶却（一作「与残」）月。","（见《说郛》卷五陈郁《藏一话腴》，校以陈岩肖《庚溪诗话》卷上。","）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-eb5dcddd-59f7-4e4a-a2e3-e20c2a0e3d47","tags":[]},{"id":"poem-4f2d666e48119ef5510282c1","title":"元日领客登北高","author":"释居简","dynasty":"宋","verses":["云绕簷楹扫不开，阑干直下是飞来。","笑看白玉芬陁利，领略风烟又一回。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.180000.json#record-224f42a8-e2f3-45ea-8a8f-c0b8825563db","tags":[]},{"id":"poem-4f2efbbc745a79e216e02e5b","title":"药轩","author":"司马光","dynasty":"宋","verses":["雨余条甲绕阶生，往往桐君昔未名。","采贮不须勤暴篲，秋阳日日满簷楹。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.30000.json#record-8eebe1ef-5d10-4b17-9e96-40a294aaf486","tags":[]},{"id":"poem-4f31dc533911e0f731a9fa02","title":"小游仙诗九十八首 八十六","author":"曹唐","dynasty":"唐","verses":["太子真娥相领行，当天合曲玉箫清。","棃花新折东风软，犹在缑山乐笑声。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-dca30bd2-ad66-4f22-8476-513998b07056","tags":[]},{"id":"poem-4f33228a10e4cb9438cd60d1","title":"邵伯埭下寄高邮陈郎中","author":"徐铉","dynasty":"宋","verses":["故人相别动经年，候馆相逢倍惨然。","顾我饮冰难辍棹，感君扶病为开筵。","河湾水浅翘愁鹭，柳岸风微噪暮蝉。","欲识酒醒魂断处，谢公祠畔客亭前。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.0.json#record-97da6aa7-cf76-4e01-ab3d-981dedadeb30","tags":[]},{"id":"poem-4f53b3e7e5d6ad4d8784af89","title":"春行","author":"李益","dynasty":"唐","verses":["侍臣朝谒罢，戚里自相过。","落日青丝骑，春风白纻歌。","恩承三殿近，猎向五陵多。","归路南桥望，垂杨拂细波。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-d7ac0c91-1a6a-497e-b9e0-888d5864ef98","tags":[]},{"id":"poem-4f5e928d121dfbf0919d45d0","title":"送独孤秀才下第归太白山","author":"陆畅","dynasty":"唐","verses":["逸翮暂时成落羽，将归太白赏灵踪。","须寻最近碧霄处，拟倩和云买一峰。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-8850b9b6-4019-4c0b-b5a1-a887c3078a87","tags":[]},{"id":"poem-4f757b1ae08b69931e65a0ce","title":"采绿","author":"佚名","dynasty":"先秦","verses":["终朝采绿，不盈一匊。予发曲局，薄言归沐。","终朝采蓝，不盈一襜。五日为期，六日不詹。","之子于狩，言韔其弓。之子于钓，言纶之绳。","其钓维何？维鲂及𫚈。维鲂及𫚈，薄言观者。"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-225","tags":[]},{"id":"poem-4f7b60b98716a2674df22a84","title":"句","author":"方君遇","dynasty":"宋","verses":["是有命焉非幸致，不知我者谓何求。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.240000.json#record-cd79b755-13a3-40d7-a5c1-3136b30886e6","tags":[]},{"id":"poem-4f8928fcbf7d80301dd7827b","title":"衞明府寄枇杷叶以诗荅","author":"司空曙","dynasty":"唐","verses":["倾筐呈绿叶，重叠色何鲜。","讵是秋风里，犹如晓露前。","仙方当见重，消疾本应便。","全胜甘蕉赠，空投谢氏篇。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-04e6eb11-0b8c-4b26-ae73-2c7dc13845dc","tags":[]},{"id":"poem-4f9dce0ccfde3928f514312e","title":"郊庙歌辞 享太庙乐章 凯安四章 一","author":"张说","dynasty":"唐","verses":["瑟彼瑶爵，亚惟上公。","室如屏气，门不容躬。","礼殷其本，乐执其中。","圣皇永慕，天地幽通。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-9cc352d4-75fb-463a-9bda-f24ff3310cb4","tags":[]},{"id":"poem-4fa216a9e2bd241e8c310f97","title":"水龙吟·年年九月西湖","author":"吕渭老","dynasty":"宋","verses":["年年九月西湖，绣船继日笙箫拥。","五云深处，红帘一桁，语莺歌凤。","群玉峰头，影娥池畔，烟霞飞动。","认蓬瀛仙子，云程路远，贪人世、瑶池梦。","要看黄尘清海，戏真珠、麻姑清纵。","曲门自有，菊金芳砌，月篦浮栋。","子著宫桃，舞翻官柳，霞杯纤捧。","待明年更把，西风妙曲，按成新弄。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.6000.json#record-112","tags":["西湖"]},{"id":"poem-4fa4c6177717ce247fe3f19a","title":"忆秦娥","author":"高明《蔡伯喈琵琶记》","dynasty":"元","verses":["长吁气，自怜薄命相遭际。","相遭际，晚年舅姑，薄情夫婿。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-4990","tags":[]},{"id":"poem-4fac3ae90144f797408113a9","title":"同观陈十六史兴碑","author":"高适","dynasty":"唐","verses":["荆衡气偏秀，江汉流不歇。","此地多精灵，有时生才杰。","伊人今独步，逸思能间发。","永怀掩风骚，千载常矻矻。","新碑亦崔嵬，佳句悬日月。","则是刊石经，终然继梼杌。","我来观雅制，慷慨变毛发。","季主尽荒淫，前王徒贻厥。","东周既削弱，两汉更沦没。","西晋何披猖，五胡相唐突。","作歌乃彰善，比物仍恶讦。","感叹将谓谁，对之空咄咄。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-2409c579-a1d8-4ea2-8fa5-790b0b45247e","tags":[]},{"id":"poem-4fbbb9935311881fb5d2f201","title":"九章·悲回风","author":"屈原","dynasty":"先秦","verses":["悲回风之摇蕙兮，心冤结而内伤。","物有微而陨性兮，声有隐而先倡。","夫何彭咸之造思兮，暨志介而不忘！","万变其情岂可盖兮，孰虚伪之可长？","鸟兽鸣以号群兮，草苴比而不芳。","鱼葺鳞以自别兮，蛟龙隐其文章。","故荼荠不同亩兮，兰茝幽而独芳。","惟佳人之永都兮，更统世以自贶。","眇远志之所及兮，怜浮云之相羊。","介眇志之所惑兮，窃赋诗之所明。","惟佳人之独怀兮，折若椒以自处。","曾歔欷之嗟嗟兮，独隐伏而思虑。","涕泣交而凄凄兮，思不眠以至曙。","终长夜之曼曼兮，掩此哀而不去。","寤从容以周流兮，聊逍遥以自恃。","伤太息之愍怜兮，气于邑而不可止。","糺思心以为𬙋兮，编愁苦以为膺。","折若木以弊光兮，随飘风之所仍。","存彷佛而不见兮，心踊跃其若汤。","抚珮衽以案志兮，超惘惘而遂行。","岁曶曶其若颓兮，时亦冉冉而将至。","薠蘅槁而节离兮，芳以歇而不比。","怜思心之不可惩兮，证此言之不可聊。","宁溘死而流亡兮，不忍此心之常愁。","孤子吟而抆泪兮，放子出而不还。","孰能思而不隐兮，照彭咸之所闻。","登石峦以远望兮，路眇眇之默默。","入景响之无应兮，闻省想而不可得。","愁郁郁之无快兮，居戚戚而不可解。","心鞿羁而不开兮，气缭转而自缔。","穆眇眇之无垠兮，莽芒芒之无仪。","声有隐而相感兮，物有纯而不可为。","邈漫漫之不可量兮，缥绵绵之不可纡。","愁悄悄之常悲兮，翩冥冥之不可娱。","凌大波而流风兮，讬彭咸之所居。","上高岩之峭岸兮，处雌蜺之标颠。","据青冥而摅虹兮，遂儵忽而扪天。","吸湛露之浮源兮，漱凝霜之雰雰。","依风穴以自息兮，忽倾寤以婵媛。","冯昆仑以澂雾兮，隐渂山以清江。","惮涌湍之礚礚兮，听波声之汹汹。","纷容容之无经兮，罔芒芒之无纪。","轧洋洋之无从兮，驰委移之焉止？","漂翻翻其上下兮，翼遥遥其左右。","泛潏潏其前后兮，伴张驰之信期。","观炎气之相仍兮，窥烟液之所积。","悲霜雪之俱下兮，听潮水之相击。","借光景以往来兮，施黄棘之枉策。","求介子之所存兮，见伯夷之放迹。","心调度而弗去兮，刻著志之无适。","曰吾怨往昔之所冀兮，悼来者之悐悐。","浮江淮而入海兮，从子胥而自适。","望大河之洲渚兮，悲申徒之抗迹。","骤谏君而不听兮，重任石之何益？","心絓结而不解兮，思蹇产而不释。"],"enabled":true,"collection":"楚辞","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/楚辞/chuci.json#record-21","tags":[]},{"id":"poem-4fbf31c74fcf6c3282beaa49","title":"送赵评事摄御史监军岭南","author":"孙逖","dynasty":"唐","verses":["议狱持邦典，临戎假宪威。","风从阊阖去，霜入洞庭飞。","篁竹迎金鼓，楼船引绣衣。","明年拜真月，南斗使星归。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-d49d11e5-8585-4003-807e-4357323c1c2e","tags":["洞庭湖"]},{"id":"poem-4fc92cdcb17934a1f4a2b465","title":"酬裴员外以诗代书","author":"高适","dynasty":"唐","verses":["少时方浩荡，遇物犹尘埃。","脱略身外事，交游天下才。","单车入燕赵，独立心悠哉。","宁知戎马间，忽展平生怀。","且欣清论高，岂顾夕阳颓。","题诗碣石馆，纵酒燕王台。","北望沙漠垂，漫天雪皑皑。","临边无策略，览古空裴回。","乐毅吾所怜，拔齐翻见猜。","荆卿吾所悲，适秦不复廻。","然诺多死地，公忠成祸胎。","与君从此辞，每恐流年催。","如何俱老大，始复忘形骸。","兄弟真二陆，声名连八裴。","乙未将星变，贼臣候天灾。","胡骑犯龙山，乘舆经马嵬。","千官无倚着，万姓徒悲哀。","诛吕鬼神动，安刘天地开。","奔波走风尘，倏忽值云雷。","拥旄出淮甸，入幕征楚材。","誓当剪鲸鲵，永以竭驽骀。","小人胡不仁，谗我成死灰。","赖得日月明，照耀无不该。","留司洛阳宫，詹府唯蒿莱。","是时扫氛祲，尚未歼渠魁。","背河列长围，师老将亦乖。","归军剧风火，散卒争椎埋。","一夕瀍洛空，生灵悲曝腮。","衣冠投草莽，予欲驰江淮。","登顿宛叶下，栖遑襄邓隈。","城池何萧条，邑屋更崩摧。","纵横荆棘丛，但见瓦砾堆。","行人无血色，战骨多青苔。","遂除彭门守，因得朝玉阶。","激昂仰鹓鹭，献替欣盐梅。","驱传及远蕃，忧思郁难排。","罢人纷争讼，赋税如山崖。","所思在畿甸，曾是鲁宓侪。","自从拜郎官，列宿焕天街。","那能访遐僻，还复寄琼瓌。","金玉本高价，埙箎终易谐。","朗咏临清秋，凉风下庭槐。","何意寇盗间，独称名义偕。","辛酸陈侯诔，叹息季鹰杯。","白日屡分手，青春不再来。","卧看中散论，愁忆太常斋。","酬赠徒为尔，长歌还自咍。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-9ca5eb72-69e6-47f0-a27d-06034645217d","tags":[]},{"id":"poem-4fd2f123b6001b65b68d1bb2","title":"玩花五首 三","author":"徐凝","dynasty":"唐","verses":["朱霞燄燄山枝动，绿野声声杜宇来。","谁为蜀王身作鸟，自啼还自有花开。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-3a1e3b5f-95ce-4547-8023-a03811b1bea9","tags":[]},{"id":"poem-4fd617b07501378a48c30b08","title":"得家书报长子仪之房下得孙男殊慰老怀时在雷州著易传适至震卦因名之曰震孙以诗寄仪之","author":"李纲","dynasty":"宋","verses":["天涯远报茁琼枝，共说鹓雏骨相奇。","鼻祖从来种桃李，耳孙自合产兰芝。","洊雷名震因观易，他日趋庭使学诗。","无复区区如尔父，定须了了胜吾儿。","书来可想开怀抱，老去何因与弄持。","素有庞翁携隐志，未应孤负鹿门期。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.90000.json#record-d8155a78-b9e4-4548-b6b0-8e169ccc85c2","tags":[]},{"id":"poem-4fd9033aaa4dcd9c09efcbda","title":"经旧游","author":"张佖","dynasty":"宋","verses":["暂到高唐晓又还，丁香结梦水潺潺。","不知云雨归何处，历历空留十二山。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.0.json#record-9d6f9c36-0578-4c8c-be9b-83d610734309","tags":[]},{"id":"poem-4fd99b380a6aca065952a39d","title":"闻馆中宣赐赏雪赋诗之会书五十六字呈秘阁侍郎","author":"李昉","dynasty":"宋","verses":["圣主怜才古所稀，转知吾道有光辉。","特宣秘府群仙会，教看遥空六出飞。","痛饮不容停盏斝，冥搜各要鬭珠玑。","仍闻中使传中旨，须尽欢娱酩酊归。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.0.json#record-446fe37e-9daf-4b60-832f-d5f4b4a28bf8","tags":[]},{"id":"poem-4fe8010a143f940bfc47a9e7","title":"家书","author":"宋伯仁","dynasty":"宋","verses":["未得还乡泪欲珠，一书封了又踌躇。","家人会得征夫意，门外西风即是书。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.210000.json#record-993ca72e-3c7e-42bc-9180-db2a9e980c6d","tags":[]},{"id":"poem-4fee9a09bd26494c302e1af3","title":"瑞鹤仙·悄郊原带郭","author":"周邦彦","dynasty":"宋","verses":["悄郊原带郭。","行路永，客去车尘漠漠。","斜阳映山落。","敛馀红、犹恋孤城栏角。","凌波步弱。","过短亭、何用素约。","有流莺劝我，重解绣鞍，缓引春酌。","不记归时早暮，上马谁扶，醒眠朱阁。","惊飙动幕。","扶残醉，绕红药。","叹西园、已是花深无地，东风何事又恶。","任流光过却。","犹喜洞天自乐。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-228","tags":["宋词三百首"]},{"id":"poem-4ff3a0ac0780fdff8a017102","title":"句  其六","author":"刘望之","dynasty":"宋","verses":["莫道南州居井底，请来此处望川原。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.120000.json#record-2f910144-14d1-4d3f-8494-fb05283c1962","tags":[]},{"id":"poem-4ff4efa8267f3802fa78e92c","title":"颂三首  其三","author":"念禅师","dynasty":"宋","verses":["元正三，上来稽首各和南。","若问香山山里事，灵源一派碧如蓝。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.60000.json#record-62f77fa0-6a3d-4905-aa92-79d33919afdd","tags":[]},{"id":"poem-4ffdeeac43c93b80300a7986","title":"题观音石壁","author":"绍兴卜者","dynasty":"宋","verses":["金紫玉青世所稀，牡丹花下探天机。","仙游秀水真消息，身傍御炉香满衣。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.120000.json#record-06b89609-31fa-4624-95b6-c6030e5dc9ed","tags":[]}];
